/*
 * PiL-HQUC stylesheet maintenance map
 *
 * This file intentionally preserves the original cascade order. Later
 * versioned sections (v22 ... v63) are compatibility patches and may override
 * earlier rules. Do not merge or reorder duplicate selectors without visual
 * regression testing across Home, Workspace, Results, drawers, and modals.
 *
 * Fast navigation:
 *   - Base tokens / shared shell: beginning of file
 *   - Workspace evolution: search "Page 02"
 *   - Operator decision board: search "Page 03"
 *   - Cost / Convergence / Conclusion: search "v48", "v53", "v63"
 *   - Current final patch: search "v137 — merge System Check"
 *   - Responsive/current overrides: search "#region 08"
 */

/* #region 01 — Base tokens, shared shell, and original page layouts */
/* =========================================================
   Quantathon React SPA — Clean CSS
   Pages: Home / Workspace / Results
   Goal: professional hackathon UI,
no-scroll desktop workspace
   ========================================================= */

/* ---------- 1. Tokens & reset ---------- */

:root {
  --bg: #050b08;
  --bg-2: #0b1f18;
  --panel: rgba(12, 30, 23, 0.78);
  --panel-2: rgba(18, 46, 35, 0.62);
  --soft: rgba(255, 255, 255, 0.045);
  --soft-2: rgba(255, 255, 255, 0.07);
  --line: rgba(192, 255, 218, 0.13);
  --text: #f1fff7;
  --muted: #9bbcad;
  --green: #42f59b;
  --cyan: #4fd7ff;
  --gold: #ffd166;
  --red: #ff6b6b;
  --blue: #91adff;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.36);
  --radius-xl: 30px;
  --radius-lg: 24px;
  --radius-md: 18px;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
}

body {
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(
      circle at 15% 12%,
      rgba(66, 245, 155, 0.17),
      transparent 30rem
    ),
    radial-gradient(
      circle at 84% 8%,
      rgba(79, 215, 255, 0.13),
      transparent 30rem
    ),
    linear-gradient(135deg, #04110c, var(--bg-2) 45%, #06110d);
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  overflow: hidden;
  overscroll-behavior: none;
}

button,
input,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  max-width: 850px;
  margin-bottom: 18px;
  font-size: clamp(42px, 6.4vw, 88px);
  line-height: 0.9;
  letter-spacing: -0.075em;
}

h2 {
  margin-bottom: 8px;
  font-size: clamp(30px, 3.6vw, 50px);
  line-height: 0.95;
  letter-spacing: -0.055em;
}

h3 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.03em;
}

/* ---------- 2. Shell & background ---------- */

.app {
  width: min(1360px, calc(100% - 28px));
  height: 100dvh;
  margin: 0 auto;
  padding: 12px 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 12px;
  overflow: hidden;
}

.app > main {
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

/* ---------- 3. Shared UI ---------- */

.panel,
.conclusion,
.winnerCard,
.chartPanel,
.resultTablePanel,
.scenarioHorizontalSection,
.dashboardSection,
.workspaceRightColumn {
  border: 1px solid var(--line);
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--panel), var(--panel-2));
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}

.kicker {
  margin: 0 0 12px;
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 12px;
  font-weight: 950;
}

.workspaceBadge,
.status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: max-content;
  padding: 10px 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.045);
  font-size: 12px;
  font-weight: 850;
}

.workspaceBadge {
  color: var(--green);
  background: rgba(66, 245, 155, 0.07);
  font-size: 16px;
}

.status {
  justify-self: end;
}

.status span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold);
}

.status.online span {
  background: var(--green);
}

.launchBtn {
  border: 0;
  border-radius: 18px;
  font-weight: 950;
  transition:
    filter 0.18s ease,
    box-shadow 0.18s ease,
    border-color 0.18s ease;
}

.launchBtn {
  color: #031009;
  background: linear-gradient(135deg, var(--green), var(--cyan));
}

button:hover {
  filter: brightness(1.05);
}

button:disabled {
  opacity: 0.65;
  cursor: wait;
}

/* ---------- 4. Navbar ---------- */

.nav {
  position: relative;
  top: auto;
  z-index: 50;
  min-height: 64px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 18px;
  margin-bottom: 0;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(5, 11, 8, 0.75);
  box-shadow: var(--shadow);
  backdrop-filter: blur(20px);
}

.brand {
  width: max-content;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  color: var(--text);
  background: transparent;
  text-align: left;
}

.brandMark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  color: #031009;
  background: linear-gradient(135deg, var(--green), var(--cyan));
  font-weight: 950;
}

.brand strong,
.brand small {
  display: block;
}

.brand small {
  color: var(--muted);
}

.navSteps,
.navCenter {
  display: flex;
  gap: 6px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
}

.navStep {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 13px;
  border: 0;
  border-radius: 999px;
  color: var(--muted);
  background: transparent;
  font-weight: 850;
}

.navStep span {
  color: var(--green);
  font-size: 11px;
}

.navStep.active {
  color: #04130c;
  background: linear-gradient(135deg, var(--green), var(--cyan));
}

/* ---------- 5. Home page ---------- */

.homeGrid {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
  gap: 16px;
  overflow: hidden;
}

.homeGrid .hero {
  height: 100%;
  padding: clamp(24px, 3.8vw, 48px);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.homeGrid .hero p,
.conclusion p,
.sectionTitle p {
  max-width: 760px;
  color: var(--muted);
  line-height: 1.55;
  font-size: 16px;
}

.trustRow,
.problemMetrics,
.scoreCards {
  display: grid;
  gap: 14px;
}

.trustRow {
  grid-template-columns: repeat(3, 1fr);
  margin-top: 22px;
}

.trustRow div {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--soft);
}

.trustRow strong {
  display: block;
  color: var(--text);
  font-size: 28px;
  letter-spacing: -0.04em;
}

.trustRow span {
  display: block;
  color: var(--muted);
}

.pulseRing {
  display: grid;
  place-items: center;
  width: 220px;
  height: 220px;
  margin: 0 auto 18px;
  border-radius: 50%;
  border: 1px solid rgba(66, 245, 155, 0.4);
  background:
    radial-gradient(circle, rgba(66, 245, 155, 0.18), transparent 58%),
    conic-gradient(
      from 140deg,
      var(--green),
      var(--cyan),
      transparent,
      var(--green)
    );
  animation: spinGlow 8s linear infinite;
}

@keyframes spinGlow {
  to {
    transform: rotate(360deg);
  }
}

.ringCore {
  display: grid;
  place-items: center;
  width: 148px;
  height: 148px;
  border-radius: 50%;
  background: rgba(5, 11, 8, 0.86);
  animation: counterSpin 8s linear infinite;
}

@keyframes counterSpin {
  to {
    transform: rotate(-360deg);
  }
}

.ringCore span {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  font-weight: 900;
}

.ringCore strong {
  font-size: 38px;
}

/* ---------- 6. Workspace page ---------- */

.workspaceViewport {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 10px;
  overflow: hidden;
}

.workspaceTop {
  min-height: 0;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
}

.workspaceTop h2 {
  margin-bottom: 4px;
  font-size: clamp(28px, 2.8vw, 42px);
}

.workspaceTop p {
  max-width: 780px;
  margin: 0;
  color: var(--muted);
  line-height: 1.35;
  font-size: 14px;
}

.workspaceLayoutContainer {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 14px;
  overflow: hidden;
}

.workspaceLeftMain {
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 12px;
  overflow: hidden;
}

.workspaceRightColumn {
  min-width: 300px;
  max-width: 340px;
  min-height: 0;
  padding: 14px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  overflow: hidden;
}

.scenarioHorizontalSection,
.dashboardSection {
  padding: 14px;
}

.dashboardSection {
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto 1fr;
  gap: 10px;
  overflow: hidden;
}

.compactHead {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 13px;
}

.compactHead h3 {
  margin: 0;
  font-size: 17px;
}

.compactHead span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

/* Horizontal scenario cards */

.scenarioHorizontalList {
  display: flex;
  gap: 10px;
  padding: 2px;
  overflow-x: auto;
  overflow-y: hidden;
}

.scenarioHorizontalCard {
  flex: 1;
  min-width: 135px;
  display: grid;
  grid-template-columns: 38px 1fr;
  align-items: center;
  gap: 10px;
  padding: 10px;
  color: var(--text);
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--soft);
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.scenarioHorizontalCard:hover {
  border-color: rgba(66, 245, 155, 0.72);
  background: linear-gradient(
    135deg,
    rgba(66, 245, 155, 0.16),
    rgba(79, 215, 255, 0.08)
  );
  box-shadow: 0 0 22px rgba(66, 245, 155, 0.12);
}

.scenarioHorizontalCard.active {
  border-color: rgba(66, 245, 155, 0.62);
  background: linear-gradient(
    135deg,
    rgba(66, 245, 155, 0.16),
    rgba(79, 215, 255, 0.06)
  );
  box-shadow: 0 0 28px rgba(66, 245, 155, 0.16);
}

.scenarioCompactIcon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 14px;
  background: rgba(66, 245, 155, 0.09);
  font-size: 21px;
}

.scenarioCardText strong {
  display: block;
  margin-bottom: 3px;
  font-size: 13px;
}

.scenarioCardText span {
  display: -webkit-box;
  overflow: hidden;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.3;
  line-clamp: 1;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
}

/* Custom editor */

.customFeaturePanel {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.customFeatureInput {
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
}

.customFeatureTop {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}

.customFeatureTop span {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 9px;
  font-weight: 950;
}

.customFeatureTop strong {
  color: var(--green);
  font-size: 10.5px;
  white-space: nowrap;
}

.customFeatureInput input[type="range"] {
  width: 100%;
  margin-bottom: 5px;
  accent-color: var(--green);
}

.customFeatureInput input[type="number"] {
  width: 100%;
  padding: 6px 8px;
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  font-size: 11px;
}

/* Dashboard */

.dashboardCompactGrid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}

.dashboardBottomRow {
  min-height: 0;
  display: grid;
  grid-template-columns: 0.82fr 1.18fr;
  gap: 10px;
}

.barsCompact {
  display: grid;
  gap: 7px;
  align-content: center;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.035);
}

.compactBarRow {
  display: grid;
  grid-template-columns: 52px 1fr 34px;
  align-items: center;
  gap: 8px;
}

.compactBarRow label,
.compactBarRow span {
  font-size: 10.5px;
  font-weight: 850;
}

.compactBarRow span {
  color: var(--muted);
  text-align: right;
}

.compactBarTrack {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
}

.compactBarFill {
  height: 100%;
  border-radius: inherit;
}

.compactBarFill.load {
  background: var(--gold);
}
.compactBarFill.solar {
  background: var(--green);
}
.compactBarFill.wind {
  background: var(--blue);
}
.compactBarFill.grid {
  background: var(--cyan);
}

.balanceAndPipeContainer {
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 8px;
}

.balanceCompact {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: linear-gradient(
    135deg,
    rgba(66, 245, 155, 0.08),
    rgba(79, 215, 255, 0.05)
  );
}

.balanceCompact span {
  display: block;
  margin-bottom: 4px;
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 9.5px;
  font-weight: 950;
}

.balanceCompact strong {
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.35;
}

.balanceCompact b {
  color: var(--gold);
  white-space: nowrap;
  font-size: 16px;
}

.pipelineCompact {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.pipeMiniStep {
  min-height: 52px;
  min-width: 0;
  display: grid;
  place-items: center;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.04);
  text-align: center;
}

.pipeMiniStep span {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  margin-bottom: 3px;
  border-radius: 50%;
  color: #031009;
  background: linear-gradient(135deg, var(--green), var(--cyan));
  font-size: 9px;
  font-weight: 950;
}

.pipeMiniStep strong {
  max-width: 100%;
  overflow: hidden;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 9.5px;
}

/* Solver panel */

.solverColumn,
.solverVerticalList {
  min-height: 0;
}

.solverVerticalList {
  display: grid;
  grid-template-rows: repeat(4, minmax(0, 1fr));
  gap: 9px;
  overflow: hidden;
}

.solverCompactCard {
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 11px;
  padding: 11px;
  color: var(--text);
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--soft);
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.solverCompactCard:hover {
  border-color: rgba(66, 245, 155, 0.55);
  box-shadow: 0 0 18px rgba(66, 245, 155, 0.1);
}

.solverCompactCard.active {
  border-color: rgba(66, 245, 155, 0.62);
  background: linear-gradient(
    135deg,
    rgba(66, 245, 155, 0.16),
    rgba(79, 215, 255, 0.06)
  );
}

.solverCardBody strong {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
}

.solverCardBody span {
  display: -webkit-box;
  overflow: hidden;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.35;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.solverTag {
  flex: 0 0 auto;
  padding: 6px 8px;
  border-radius: 999px;
  color: var(--green);
  background: rgba(66, 245, 155, 0.08);
  font-size: 9px;
  font-style: normal;
  font-weight: 950;
}

.solverFooter {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.miniFlowText {
  padding: 9px 10px;
  border: 1px dashed var(--line);
  border-radius: 16px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.035);
  font-size: 10.5px;
  line-height: 1.4;
}

.workspaceLaunch {
  width: 100%;
  min-height: 46px;
  margin: 0;
}

/* ---------- 7. Results page ---------- */

.results {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto auto 1fr auto;
  gap: 12px;
  overflow: hidden;
}

.sectionTitle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 0;
}

.results .sectionTitle h2 {
  font-size: clamp(28px, 3vw, 44px);
}

.results .sectionTitle p {
  max-width: 760px;
  margin-bottom: 0;
  color: var(--muted);
  line-height: 1.35;
  font-size: 14px;
}

.climaxGrid {
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 14px;
}

.winnerCard,
.chartPanel,
.resultTablePanel,
.conclusion {
  padding: 16px 18px;
}

.winnerCard h3 {
  margin: 8px 0;
  font-size: 28px;
}

.winnerCard p {
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.bitstringBox {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--soft);
}

.bitstringBox span,
.conclusion span,
.winnerCard span {
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 11px;
  font-weight: 950;
}

.bitstringBox strong {
  display: block;
  margin-top: 8px;
  color: var(--gold);
  font-family: Consolas, "SFMono-Regular", monospace;
  font-size: 15px;
  word-break: break-all;
}

.scoreCards {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.chartGrid {
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 0;
}

.chartPanel .panelHead {
  display: flex;
  justify-content: space-between;
  margin-bottom: 12px;
}

.bars {
  display: grid;
  gap: 14px;
}

.chartRow {
  display: grid;
  grid-template-columns: 62px 1fr 82px;
  gap: 10px;
  align-items: center;
}

.chartLabel {
  color: var(--text);
  font-weight: 900;
}

.chartTrack {
  height: 16px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
}

.chartFill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--gold), #ff9f1c);
}

.chartFill.quantum {
  background: linear-gradient(90deg, var(--green), var(--cyan));
}

.chartValue {
  color: var(--muted);
  text-align: right;
  font-weight: 900;
}

.resultTablePanel {
  min-height: 0;
  overflow: hidden;
}

table {
  width: 100%;
  min-width: 0;
  border-collapse: collapse;
  font-size: 12px;
}

th,
td {
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  text-align: left;
}

th {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 11px;
}

.conclusion p {
  max-width: none;
  margin: 6px 0 0;
  color: var(--muted);
  line-height: 1.45;
  font-size: 14px;
}

/* ---------- 8. Animations & responsive fallback ---------- */

.pageEnter {
  animation: pageEnter 0.38s ease both;
}

@keyframes pageEnter {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.99);
  }
}

@media (max-width: 1099px), (max-height: 719px) {
  html,
  body,
  #root {
    overflow: auto;
  }

  body {
    overflow-x: hidden;
  }

  .app {
    height: auto;
    min-height: 100dvh;
    overflow: visible;
  }

  .app > main,
  .homeGrid,
  .workspaceViewport,
  .results {
    height: auto;
    overflow: visible;
  }

  .nav {
    grid-template-columns: 1fr;
    border-radius: 28px;
  }

  .status {
    justify-self: start;
  }

  .navSteps,
  .navCenter {
    justify-content: center;
    flex-wrap: wrap;
  }

  .homeGrid,
  .workspaceLayoutContainer,
  .dashboardBottomRow,
  .climaxGrid,
  .chartGrid {
    grid-template-columns: 1fr;
  }

  .workspaceRightColumn {
    max-width: none;
  }

  .scenarioHorizontalList {
    flex-wrap: wrap;
  }

  .scenarioHorizontalCard {
    flex: 1 1 180px;
  }

  .dashboardCompactGrid,
  .scoreCards,
  .trustRow {
    grid-template-columns: repeat(3, 1fr);
  }

  .customFeaturePanel {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 720px) {
  .app {
    width: min(100% - 20px, 1360px);
  }

  h1 {
    font-size: 44px;
  }

  .panel,
  .winnerCard,
  .chartPanel,
  .resultTablePanel,
  .conclusion,
  .scenarioHorizontalSection,
  .dashboardSection,
  .workspaceRightColumn {
    padding: 18px;
  }

  .dashboardCompactGrid,
  .scoreCards,
  .trustRow,
  .customFeaturePanel {
    grid-template-columns: 1fr;
  }

  .chartRow {
    grid-template-columns: 64px 1fr;
  }

  .chartValue {
    grid-column: 2;
    text-align: left;
  }
}

/* Home hero title: force 4-line layout */

.resultsBadge {
  padding: 12px 18px;
  border-radius: 999px;
  background: rgba(0, 255, 195, 0.08);
  border: 1px solid rgba(0, 255, 195, 0.18);
  color: #18f5d0;
  font-weight: 700;
  white-space: nowrap;
}

.resultKpiGrid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}

.resultKpiCard {
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.resultKpiCard.accent {
  box-shadow: 0 0 0 1px rgba(0, 255, 195, 0.08) inset;
}

.resultKpiCard span {
  font-size: 12px;
  text-transform: uppercase;
  color: #8ea6a2;
  letter-spacing: 0.08em;
}

.resultChartsGrid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 16px;
}

.chartPanel,
.resultTableCard,
.resultInsightCard {
  border-radius: 24px;
  padding: 18px;
  background: linear-gradient(
    180deg,
    rgba(7, 30, 26, 0.92),
    rgba(7, 23, 22, 0.9)
  );
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.chartWrap {
  height: 360px;
}

.resultsBottomGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.insightBox {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.insightBox p {
  margin: 0;
  line-height: 1.7;
  color: #d8ece8;
}

@media (max-width: 1280px) {
  .resultKpiGrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .resultChartsGrid,
  .resultsBottomGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 820px) {
  .resultKpiGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chartWrap {
    height: 300px;
  }
}

/* Advanced Results Page: KPI + Toggle Charts + Animations */

.resultKpiCard,
.insightPanel,
.resultTableCard,
.finalConclusionCard {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: linear-gradient(
    135deg,
    rgba(12, 30, 23, 0.78),
    rgba(18, 46, 35, 0.62)
  );
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
}

.resultKpiCard span {
  display: block;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.09em;
  font-size: 10px;
  font-weight: 950;
}

.resultKpiGrid.advanced {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}

.resultKpiCard {
  min-width: 0;
  min-height: 92px;
  padding: 13px;
  background: rgba(255, 255, 255, 0.045);
}

.resultKpiCard.accent {
  border-color: rgba(66, 245, 155, 0.42);
  background: rgba(66, 245, 155, 0.075);
}

.resultKpiCard strong {
  display: block;
  overflow: hidden;
  margin: 7px 0 4px;
  color: var(--text);
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
  letter-spacing: -0.04em;
}

.resultKpiCard small {
  display: block;
  overflow: hidden;
  color: var(--muted);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.monoValue {
  color: var(--gold) !important;
  font-family: Consolas, "SFMono-Regular", monospace;
  font-size: 13px !important;
  letter-spacing: 0 !important;
}

.resultAnimate {
  opacity: 0;
  transform: translateY(10px);
  animation: fadeRise 0.48s ease forwards;
}

@keyframes fadeRise {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.advancedResultsGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.7fr);
  gap: 12px;
}

.insightPanel,
.resultTableCard,
.finalConclusionCard {
  min-height: 0;
  padding: 15px;
  border-radius: 22px;
}

@keyframes growDispatch {
  from {
    transform: scaleY(0);
  }
}

.loadMarker {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  opacity: 0;
  transform: scaleX(0.28);
  transform-origin: center;
  background: rgba(235, 255, 247, 0.78);
  box-shadow: 0 0 5px rgba(235, 255, 247, 0.22);
  animation: revealLoadMarker 0.18s ease-out both;
  pointer-events: none;
}

@keyframes revealLoadMarker {
  from {
    opacity: 0;
    transform: scaleX(0.28);
  }

  to {
    opacity: 1;
    transform: scaleX(1);
  }
}

.qaoaPath,
.milpPath {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.qaoaPath {
  stroke: var(--green);
  stroke-width: 4;
  stroke-dasharray: 1200;
  stroke-dashoffset: 1200;
  animation: drawLine 1.35s ease forwards;
}

.milpPath {
  stroke: var(--gold);
  stroke-width: 3;
  stroke-dasharray: 9 8;
  opacity: 0.95;
}

@keyframes drawLine {
  to {
    stroke-dashoffset: 0;
  }
}

.qaoaDot {
  fill: var(--green);
  stroke: #031009;
  stroke-width: 2;
}

.breakdownColumn {
  min-height: 0;
  display: grid;
  gap: 10px;
  align-content: start;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.028);
}

.breakdownColumn h4 {
  margin: 0 0 4px;
  color: var(--text);
}

@keyframes growWidth {
  from {
    width: 0;
  }
}

.insightPanel {
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 10px;
}

.bitstringShowcase {
  padding: 12px;
  border: 1px solid rgba(255, 209, 102, 0.28);
  border-radius: 16px;
  background: rgba(255, 209, 102, 0.07);
}

.bitstringShowcase span {
  display: block;
  margin-bottom: 6px;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.09em;
  font-size: 10px;
  font-weight: 950;
}

.bitstringShowcase strong {
  color: var(--gold);
  word-break: break-all;
  font-family: Consolas, "SFMono-Regular", monospace;
  font-size: 13px;
}

.comparisonAndConclusion {
  min-height: 0;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 12px;
}

.resultTableCard,
.finalConclusionCard {
  overflow: hidden;
}

.finalConclusionCard span {
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 10px;
  font-weight: 950;
}

.finalConclusionCard p {
  margin: 8px 0 0;
  color: var(--muted);
  line-height: 1.45;
  font-size: 13px;
}

.finalConclusionCard strong {
  color: var(--green);
}

@media (max-width: 1180px) {
  .resultKpiGrid.advanced {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .advancedResultsGrid,
  .comparisonAndConclusion {
    grid-template-columns: 1fr;
  }
}

@media (max-height: 760px) and (min-width: 1181px) {
  .resultKpiCard {
    padding: 10px;
  }

  .resultKpiCard {
    min-height: 76px;
  }

  .resultKpiCard strong {
    font-size: 17px;
  }
}

/* ============================================================
   Advanced Workspace UX: clamped inputs + diesel + clean metrics
   ============================================================ */

.customFeatureInput.compactField {
  padding: 8px;
}

.customFeatureMeta {
  margin: -2px 0 5px;
}

.customFeatureMeta small {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
}

.customFeatureInput input[type="number"] {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

.advancedUXMetrics {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.uxMetricCard {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
}

.uxMetricCard span {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 9px;
  font-weight: 950;
}

.uxMetricCard strong {
  display: block;
  color: var(--text);
  font-size: 18px;
  letter-spacing: -0.04em;
}

.uxMetricCard small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
}

.uxMetricCard.cleanGlow {
  border-color: rgba(66, 245, 155, 0.35);
  background: rgba(66, 245, 155, 0.075);
}

.uxMetricCard.cleanGlow strong {
  color: var(--green);
}

.uxMetricCard.breakerDangerGlow {
  border-color: rgba(255, 107, 107, 0.55);
  background: rgba(255, 107, 107, 0.09);
  box-shadow: 0 0 24px rgba(255, 107, 107, 0.15);
}

.uxMetricCard.breakerDangerGlow strong {
  color: var(--red);
}

.compactBarFill.diesel-active {
  background: linear-gradient(90deg, #ff7f50, #ff3b30);
  box-shadow: 0 0 14px rgba(255, 127, 80, 0.4);
}

.compactBarFill.diesel-muted {
  background: rgba(148, 163, 184, 0.32);
}

.compactBarFill.grid-danger {
  background: linear-gradient(90deg, var(--red), #ff9f1c);
  box-shadow: 0 0 14px rgba(255, 107, 107, 0.35);
}

/* ============================================================
   Workspace V2: five feature cards + bottom insight row
   Paste this at the end of static/styles.css
   ============================================================ */

.workspaceV2Dashboard {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.workspaceV2Dashboard .customFeaturePanel,
.workspaceV2Dashboard .dashboardCompactGrid,
.workspaceV2Dashboard .advancedUXMetrics,
.workspaceV2Dashboard .dashboardBottomRow,
.workspaceV2Dashboard .pipelineCompact {
  display: none !important;
}

.featureControlGrid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.featureControlCard {
  min-width: 0;
  min-height: 156px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.04);
}

.featureControlCard.load {
  border-color: rgba(255, 209, 102, 0.26);
}

.featureControlCard.solar,
.featureControlCard.wind {
  border-color: rgba(66, 245, 155, 0.26);
}

.featureControlCard.grid,
.featureControlCard.grid-danger {
  border-color: rgba(79, 215, 255, 0.26);
}

.featureControlCard.battery {
  border-color: rgba(181, 140, 255, 0.26);
}

.featureControlCard.grid-danger {
  border-color: rgba(255, 107, 107, 0.52);
  box-shadow: 0 0 20px rgba(255, 107, 107, 0.11);
}

.featureCardTop {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.featureCardTop span {
  display: block;
  margin-bottom: 8px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.09em;
  font-size: 10px;
  font-weight: 950;
}

.featureValueEditor {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
}

.featureValueEditor input {
  width: 72px;
  min-width: 0;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
  font: inherit;
  font-size: 21px;
  font-weight: 850;
  letter-spacing: -0.045em;
  line-height: 1.05;
  appearance: textfield;
}

.featureValueEditor input::-webkit-inner-spin-button,
.featureValueEditor input::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
}

.featureValueEditor b {
  color: var(--text);
  font-size: 18px;
  font-weight: 850;
}

.featureCardTop small {
  flex: 0 0 auto;
  color: var(--green);
  font-size: 10px;
  font-weight: 850;
}

.featureRange {
  --feature-color: var(--cyan);
  width: 100%;
  height: 12px;
  margin: 18px 0 12px;
  border: 0;
  border-radius: 999px;
  outline: 0;
  appearance: none;
  cursor: pointer;
  background: linear-gradient(
    90deg,
    var(--feature-color) 0 var(--feature-progress),
    rgba(255, 255, 255, 0.08) var(--feature-progress) 100%
  );
}

.featureRange.load {
  --feature-color: var(--gold);
}

.featureRange.solar,
.featureRange.wind {
  --feature-color: var(--green);
}

.featureRange.grid {
  --feature-color: var(--cyan);
}

.featureRange.grid-danger {
  --feature-color: var(--red);
  box-shadow: 0 0 14px rgba(255, 107, 107, 0.24);
}

.featureRange.battery {
  --feature-color: #b58cff;
}

.featureRange::-webkit-slider-thumb {
  width: 18px;
  height: 18px;
  border: 3px solid var(--feature-color);
  border-radius: 50%;
  background: #eafff4;
  box-shadow: 0 0 0 3px rgba(5, 11, 8, 0.45);
  appearance: none;
}

.featureRange::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border: 3px solid var(--feature-color);
  border-radius: 50%;
  background: #eafff4;
  box-shadow: 0 0 0 3px rgba(5, 11, 8, 0.45);
}

.featureCardFoot {
