/* ============================================================
   Fix Results tab bar overlap / clipped text
   ============================================================ */

.advancedResultsGrid {
  min-height: 0;
  position: relative;
  z-index: 1;
}

/* ============================================================
   Pre-Optimization Intelligence
   Panel 1: 24h operational stress
   Panel 2: Feasibility and decision preview
   ============================================================ */

.preOptimizationPanel {
  flex: 1;
  min-height: 285px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  overflow: hidden;
  border: 1px solid rgba(66, 245, 155, 0.18);
  border-radius: 20px;
  background:
    linear-gradient(
      135deg,
      rgba(66, 245, 155, 0.035),
      rgba(79, 215, 255, 0.018)
    ),
    rgba(255, 255, 255, 0.018);
}

.preOptimizationHead,
.intelligenceHead,
.feasibilityHead {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.preOptimizationHead > div:first-child > span,
.intelligenceHead span,
.feasibilityHead span {
  display: block;
  margin-bottom: 3px;
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 9px;
  font-weight: 950;
}

.preOptimizationHead h3,
.intelligenceHead h4,
.feasibilityHead h4 {
  margin: 0;
  color: var(--text);
  letter-spacing: -0.025em;
}

.preOptimizationHead h3 {
  font-size: 15px;
}

.intelligenceHead h4,
.feasibilityHead h4 {
  font-size: 14px;
}

.readinessBadge,
.intelligenceHead em {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.035);
  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  white-space: nowrap;
}

.readinessBadge i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.readinessBadge.safe {
  color: var(--green);
  border-color: rgba(66, 245, 155, 0.28);
  background: rgba(66, 245, 155, 0.07);
}

.readinessBadge.safe i {
  background: var(--green);
  box-shadow: 0 0 10px rgba(66, 245, 155, 0.4);
}

.readinessBadge.watch {
