/* ============================================================
   Vertical Workflow Dock — full-height workflow spine
   The dock now matches the full-height split transition. It stays
   compact by default and expands over content without shifting it.
   ============================================================ */

.app {
  width: 100%;
  max-width: none;
  height: 100dvh;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 78px minmax(0, 1fr);
  grid-template-rows: 1fr;
  gap: 0;
  overflow: hidden;
}

.appMain {
  grid-column: 2;
  min-width: 0;
  min-height: 0;
  height: 100dvh;
  padding: 10px 16px 10px 2px;
  overflow: hidden;
}

.appContent {
  width: min(1460px, 100%);
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0 auto;
  overflow: hidden;
}

.appContent > .workspaceViewport {
  width: 100%;
  height: 100%;
  min-height: 0;
}

.workflowDock {
  position: fixed;
  z-index: 120;
  top: 8px;
  bottom: 8px;
  left: 8px;
  width: 62px;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 10px;
  padding: 10px 8px;
  overflow: hidden;
  border: 1px solid rgba(192, 255, 218, 0.16);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 28px 32px,
      rgba(66, 245, 155, 0.14),
      transparent 118px
    ),
    radial-gradient(
      circle at 25% 72%,
      rgba(79, 215, 255, 0.055),
      transparent 210px
    ),
    linear-gradient(180deg, rgba(4, 25, 18, 0.975), rgba(2, 13, 9, 0.985));
  box-shadow:
    0 28px 82px rgba(0, 0, 0, 0.46),
    0 0 0 1px rgba(255, 255, 255, 0.018) inset,
    0 1px 0 rgba(255, 255, 255, 0.05) inset;
  backdrop-filter: blur(25px) saturate(128%);
  transition:
    width 0.26s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.workflowDock::after {
  content: "";
  position: absolute;
  top: 24px;
  right: 0;
  bottom: 24px;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    rgba(66, 245, 155, 0.34) 28%,
    rgba(79, 215, 255, 0.22) 72%,
    transparent
  );
  opacity: 0.68;
  pointer-events: none;
}

.workflowDock:hover,
.workflowDock:focus-within {
  width: 220px;
  border-color: rgba(66, 245, 155, 0.3);
  background:
    radial-gradient(
      circle at 34px 36px,
      rgba(66, 245, 155, 0.16),
      transparent 145px
    ),
    radial-gradient(
      circle at 30% 72%,
      rgba(79, 215, 255, 0.07),
      transparent 250px
    ),
    linear-gradient(180deg, rgba(4, 27, 19, 0.988), rgba(2, 13, 9, 0.988));
  box-shadow:
    22px 0 88px rgba(0, 0, 0, 0.5),
    0 0 38px rgba(66, 245, 155, 0.07),
    0 0 0 1px rgba(255, 255, 255, 0.022) inset,
    0 1px 0 rgba(255, 255, 255, 0.055) inset;
}

.dockBrand {
  position: relative;
  width: 100%;
  min-width: 0;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 0 0 11px;
  border: 0;
  border-bottom: 1px solid rgba(192, 255, 218, 0.1);
  color: var(--text);
  background: transparent;
  text-align: left;
}

.dockBrandMark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(79, 215, 255, 0.24);
  border-radius: 16px;
  color: #02110a;
  background: linear-gradient(135deg, var(--green), var(--cyan));
  box-shadow:
    0 10px 24px rgba(66, 245, 155, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.42);
  font-size: 15px;
  font-weight: 950;
}

.dockBrandCopy,
.workflowStepCopy,
.dockStatusCopy {
  min-width: 0;
  max-width: 0;
  opacity: 0;
  overflow: hidden;
  transform: translateX(-7px);
  transition:
    max-width 0.24s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.14s ease,
    transform 0.22s cubic-bezier(0.22, 1, 0.36, 1);
  white-space: nowrap;
}

.workflowDock:hover .dockBrandCopy,
.workflowDock:focus-within .dockBrandCopy,
.workflowDock:hover .workflowStepCopy,
.workflowDock:focus-within .workflowStepCopy,
.workflowDock:hover .dockStatusCopy,
.workflowDock:focus-within .dockStatusCopy {
  max-width: 148px;
  opacity: 1;
  transform: translateX(0);
  transition-delay: 0.035s;
}

.dockBrandCopy strong,
.dockBrandCopy small,
.workflowStepCopy strong,
.workflowStepCopy small,
.dockStatusCopy strong,
.dockStatusCopy small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dockBrandCopy strong {
  color: var(--text);
  font-size: 13px;
  letter-spacing: -0.025em;
}

.dockBrandCopy small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9px;
}

.workflowSteps {
  --workflow-progress: 0;
  position: relative;
  align-self: center;
  width: 100%;
  min-height: 224px;
  display: grid;
  grid-template-rows: repeat(3, 58px);
  align-content: center;
  gap: 10px;
  padding: 4px 0;
}

.workflowRail,
.workflowRailProgress {
  position: absolute;
  z-index: 0;
  top: 33px;
  bottom: 33px;
  left: 21px;
  width: 2px;
  border-radius: 999px;
  transform-origin: top center;
}

.workflowRail {
  background: rgba(192, 255, 218, 0.11);
}

.workflowRailProgress {
  background: linear-gradient(180deg, var(--green), var(--cyan));
  box-shadow: 0 0 11px rgba(66, 245, 155, 0.38);
  transform: scaleY(var(--workflow-progress));
  transition: transform 0.34s cubic-bezier(0.22, 1, 0.36, 1);
}

.workflowStep {
  position: relative;
  z-index: 1;
  width: 100%;
  min-width: 0;
  min-height: 58px;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  border: 1px solid transparent;
  border-radius: 17px;
  color: var(--muted);
  background: transparent;
  text-align: left;
  transition:
    color 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease,
    padding 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}

.workflowDock:hover .workflowStep,
.workflowDock:focus-within .workflowStep {
  padding: 7px 8px 7px 0;
}

.workflowStep:hover {
  color: var(--text);
}

.workflowDock:hover .workflowStep:hover,
.workflowDock:focus-within .workflowStep:hover {
  background: rgba(255, 255, 255, 0.035);
}

.workflowDock:hover .workflowStep.active,
.workflowDock:focus-within .workflowStep.active {
  color: var(--text);
  border-color: rgba(66, 245, 155, 0.28);
  background: linear-gradient(
    135deg,
    rgba(66, 245, 155, 0.14),
    rgba(79, 215, 255, 0.05)
  );
  box-shadow:
    0 12px 26px rgba(0, 0, 0, 0.18),
    0 0 24px rgba(66, 245, 155, 0.06);
}

.workflowStep.active::after {
  content: "";
  position: absolute;
  top: 13px;
  right: 6px;
  bottom: 13px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(180deg, var(--green), var(--cyan));
  opacity: 0;
  transition: opacity 0.16s ease;
}

.workflowDock:hover .workflowStep.active::after,
.workflowDock:focus-within .workflowStep.active::after {
  opacity: 1;
}

.workflowNode {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(192, 255, 218, 0.15);
  border-radius: 15px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.032);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.02);
  font-size: 9px;
  font-weight: 950;
  transition:
    color 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease;
}

.workflowStep:hover .workflowNode {
  transform: translateY(-1px);
}

.workflowStep.active .workflowNode {
  color: #02110a;
  border-color: rgba(255, 255, 255, 0.2);
  background: linear-gradient(135deg, var(--green), var(--cyan));
  box-shadow:
    0 0 0 4px rgba(66, 245, 155, 0.075),
    0 10px 24px rgba(66, 245, 155, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.38);
}

.workflowStep.completed .workflowNode {
  color: var(--green);
  border-color: rgba(66, 245, 155, 0.3);
  background: rgba(66, 245, 155, 0.075);
  box-shadow: 0 0 14px rgba(66, 245, 155, 0.06);
  font-size: 13px;
}

.workflowStepCopy strong {
  color: inherit;
  font-size: 12px;
  letter-spacing: -0.015em;
}

.workflowStepCopy small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 8.5px;
}

.dockStatus {
  width: 100%;
  min-width: 0;
  min-height: 50px;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 11px 0 0;
  border-top: 1px solid rgba(192, 255, 218, 0.1);
  color: var(--muted);
}

.dockStatusDot {
  justify-self: center;
  width: 10px;
  height: 10px;
  border: 2px solid rgba(4, 20, 14, 0.9);
  border-radius: 50%;
  background: var(--gold);
  box-shadow:
    0 0 0 5px rgba(255, 209, 102, 0.055),
    0 0 13px rgba(255, 209, 102, 0.34);
}

.dockStatus.online .dockStatusDot {
  background: var(--green);
  box-shadow:
    0 0 0 5px rgba(66, 245, 155, 0.055),
    0 0 14px rgba(66, 245, 155, 0.4);
}

.dockStatus.mock .dockStatusDot {
  background: var(--gold);
}

.dockStatusCopy strong {
  color: var(--text);
  font-size: 10px;
}

.dockStatusCopy small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 8px;
}

/* The dock is the single global location for connection state. */
.workspaceTop {
  align-items: flex-start;
}

/* Full-height split transition, visually continuous with the dock. */
.workflowSplitTransition {
  position: fixed;
  z-index: 240;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  animation: workflowSplitShell 0.56s ease both;
}

.workflowSplitBeam {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(34vw, 430px);
  background:
    radial-gradient(
      circle at 44px 50%,
      rgba(66, 245, 155, 0.14),
      transparent 190px
    ),
    linear-gradient(135deg, rgba(4, 27, 18, 0.995), rgba(2, 13, 9, 0.98));
  border-right: 1px solid rgba(66, 245, 155, 0.34);
  box-shadow: 24px 0 78px rgba(0, 0, 0, 0.44);
  clip-path: polygon(0 0, 90% 0, 100% 50%, 90% 100%, 0 100%);
  transform-origin: left center;
  animation: workflowSplitBeam 0.56s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.workflowSplitMessage {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: clamp(94px, 7.5vw, 126px);
  display: grid;
  gap: 5px;
  transform: translateY(-50%);
  animation: workflowSplitCopy 0.56s ease both;
}

.workflowSplitMessage > span {
  color: var(--green);
  letter-spacing: 0.18em;
  font-size: 10px;
  font-weight: 950;
}

.workflowSplitMessage strong {
  color: var(--text);
  font-size: clamp(32px, 3.2vw, 48px);
  line-height: 0.94;
  letter-spacing: -0.052em;
}

.workflowSplitMessage small {
  color: var(--muted);
  font-size: 11px;
}

@keyframes workflowSplitShell {
  0%,
  100% {
    opacity: 0;
  }
  15%,
  70% {
    opacity: 1;
  }
}

@keyframes workflowSplitBeam {
  0% {
    opacity: 0;
    transform: translateX(-100%) scaleX(0.46);
  }

  28%,
  67% {
    opacity: 1;
    transform: translateX(0) scaleX(1);
  }

  100% {
    opacity: 0;
    transform: translateX(-16%) scaleX(0.8);
  }
}

@keyframes workflowSplitCopy {
  0%,
  18% {
    opacity: 0;
    transform: translate(-15px, -50%);
  }

  35%,
  67% {
    opacity: 1;
    transform: translate(0, -50%);
  }

  100% {
    opacity: 0;
    transform: translate(13px, -50%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .workflowDock,
  .dockBrandCopy,
  .workflowStepCopy,
  .dockStatusCopy,
  .workflowRailProgress,
  .workflowStep,
  .workflowNode {
    transition: none;
  }

  .workflowSplitTransition,
  .workflowSplitBeam,
  .workflowSplitMessage {
    animation-duration: 0.01ms;
  }
}

