/* ============================================================
   QAOA Convergence: objective trace + formulation summary
   ============================================================ */

.qaoaConvergenceLayout {
  height: calc(100% - 44px);
  min-height: 270px;
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(250px, 0.9fr);
  gap: 12px;
  overflow: hidden;
}

.qaoaConvergenceGraph,
.quantumRunPanel {
  min-width: 0;
