  border-radius: 18px;
  background: rgba(255, 255, 255, 0.028);
}

.qaoaConvergenceGraph {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 8px;
  padding: 10px;
  overflow: hidden;
}

.quantumRunHead {
