/* ============================================================
   Final polish — dock layering, overflow safety, and full QAOA map
   ============================================================ */

/* Give expanded labels enough room while keeping the dock overlay-based. */
.workflowDock:hover,
.workflowDock:focus-within {
  width: 246px;
}

.workflowDock,
.workflowDock * {
  box-sizing: border-box;
}

.dockBrand,
.workflowStep,
.dockStatus {
  isolation: isolate;
}

/* Connector rail must sit underneath every numbered node. */
.workflowSteps {
  isolation: isolate;
}

.workflowRail,
.workflowRailProgress {
  z-index: 0;
  pointer-events: none;
}

.workflowStep {
  z-index: 2;
  overflow: hidden;
}

.workflowNode {
  position: relative;
  z-index: 4;
  flex: 0 0 auto;
  overflow: visible;
  white-space: nowrap;
  isolation: isolate;
  background: rgba(7, 28, 20, 0.985);
  box-shadow:
    0 0 0 4px rgba(4, 20, 14, 0.92),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.workflowStep.pending .workflowNode {
  background: rgba(7, 28, 20, 0.985);
}

.workflowStep.completed .workflowNode {
  background: rgb(7, 38, 26);
