/* ============================================================
   Dock final fix — text-safe expansion and connector occlusion
   ============================================================ */

/* A wider overlay gives every label a real text column. */
.workflowDock {
  --dock-expanded-width: 280px;
  --dock-cutout: #03160f;
}

.workflowDock:hover,
.workflowDock:focus-within {
  width: min(var(--dock-expanded-width), calc(100vw - 20px));
}

/* Do not let a button clip its own label. The dock boundary still
   controls the collapsed/expanded reveal. */
.workflowStep {
  overflow: visible;
  isolation: isolate;
}

/* Opaque cut-out above the rail and below the complete outer node.
   This hides both the base rail and glowing progress rail beneath
   the entire rounded square, not only beneath the number glyph. */
.workflowStep::before {
  content: "";
  position: absolute;
  z-index: 1;
  left: -5px;
  top: 50%;
  width: 54px;
  height: 54px;
  border-radius: 19px;
  background: var(--dock-cutout);
  transform: translateY(-50%);
  pointer-events: none;
}

.workflowRail,
.workflowRailProgress {
  z-index: 0;
}

.workflowNode {
  position: relative;
  z-index: 3;
  overflow: hidden;
  background: #082219;
  box-shadow:
    0 0 0 5px var(--dock-cutout),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.workflowStep.pending .workflowNode {
  background: #082219;
}

.workflowStep.completed .workflowNode {
  background: #073520;
  box-shadow:
    0 0 0 5px var(--dock-cutout),
    0 0 14px rgba(66, 245, 155, 0.09),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.workflowStep.active .workflowNode {
  box-shadow:
    0 0 0 5px var(--dock-cutout),
    0 10px 24px rgba(66, 245, 155, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.38);
}

/* Keep all textual content above the cut-out and rail. */
.workflowStepCopy,
.dockBrandCopy,
.dockStatusCopy {
  position: relative;
  z-index: 4;
  min-width: 0;
  width: auto;
  max-width: none;
  overflow: visible;
  white-space: normal;
}

/* Collapsed state: visually hide copy without imposing a width that
   can remain stale when the dock expands. */
.workflowDock:not(:hover):not(:focus-within) .dockBrandCopy,
.workflowDock:not(:hover):not(:focus-within) .workflowStepCopy,
.workflowDock:not(:hover):not(:focus-within) .dockStatusCopy {
  width: 0;
  opacity: 0;
  visibility: hidden;
  overflow: hidden;
  pointer-events: none;
}

.workflowDock:hover .dockBrandCopy,
.workflowDock:focus-within .dockBrandCopy,
.workflowDock:hover .workflowStepCopy,
.workflowDock:focus-within .workflowStepCopy,
.workflowDock:hover .dockStatusCopy,
.workflowDock:focus-within .dockStatusCopy {
  width: auto;
  max-width: none;
  opacity: 1;
  visibility: visible;
  overflow: visible;
  transform: translateX(0);
}

/* Remove ellipsis/clipping and allow a controlled second line at any
   browser zoom level. */
.dockBrandCopy strong,
.dockBrandCopy small,
.workflowStepCopy strong,
.workflowStepCopy small,
.dockStatusCopy strong,
.dockStatusCopy small {
  width: 100%;
  max-width: none;
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: normal;
}

.dockBrandCopy strong {
  font-size: 13px;
  line-height: 1.16;
}

.dockBrandCopy small {
  line-height: 1.28;
}

.workflowStepCopy strong {
  font-size: 12px;
  line-height: 1.2;
}

.workflowStepCopy small {
  margin-top: 3px;
  font-size: 8.5px;
  line-height: 1.28;
}

.dockStatusCopy strong,
.dockStatusCopy small {
  line-height: 1.25;
}

/* Guarantee a usable text track after internal padding and the active
   state indicator are accounted for. */
.workflowDock:hover .dockBrand,
.workflowDock:focus-within .dockBrand,
.workflowDock:hover .workflowStep,
.workflowDock:focus-within .workflowStep,
.workflowDock:hover .dockStatus,
.workflowDock:focus-within .dockStatus {
  grid-template-columns: 44px minmax(0, 1fr);
  column-gap: 12px;
  padding-right: 16px;
}

.workflowDock:hover .workflowStep.active,
.workflowDock:focus-within .workflowStep.active {
  padding-right: 18px;
}

.workflowStep.active::after {
  z-index: 5;
}

