/* ============================================================
   Unified full-height application shell
   The content frame now shares the same vertical inset and height
   as the workflow dock, so both surfaces read as one interface.
   ============================================================ */

:root {
  --app-shell-inset: 8px;
  --dock-collapsed-width: 62px;
  --dock-content-gap: 8px;
  --app-shell-radius: 24px;
}

.app {
  grid-template-columns:
    calc(
      var(--app-shell-inset) + var(--dock-collapsed-width) +
        var(--dock-content-gap)
    )
    minmax(0, 1fr);
}

/* Match the dock's exact top and bottom edges. */
.appMain {
  position: relative;
  grid-column: 2;
  width: auto;
  height: calc(100dvh - (var(--app-shell-inset) * 2));
  min-height: 0;
  margin: var(--app-shell-inset) var(--app-shell-inset) var(--app-shell-inset) 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid rgba(192, 255, 218, 0.14);
  border-radius: var(--app-shell-radius);
  background:
    radial-gradient(
      circle at 8% 10%,
      rgba(66, 245, 155, 0.055),
      transparent 29rem
    ),
    radial-gradient(
      circle at 94% 12%,
      rgba(79, 215, 255, 0.045),
      transparent 31rem
    ),
    linear-gradient(135deg, rgba(4, 24, 17, 0.74), rgba(3, 18, 13, 0.58));
  box-shadow:
    0 26px 78px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(13px);
}

/* A subtle shared seam makes the dock and content feel attached. */
.appMain::before {
  content: "";
  position: absolute;
  z-index: 3;
  top: 22px;
  bottom: 22px;
  left: 0;
  width: 1px;
  background: linear-gradient(
    180deg,
    transparent,
    rgba(66, 245, 155, 0.25) 28%,
    rgba(79, 215, 255, 0.17) 72%,
    transparent
  );
  pointer-events: none;
}

.appContent {
  width: 100%;
  max-width: none;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 10px 14px 10px 10px;
  overflow: hidden;
}

/* Keep the dock on the same geometric shell. */
.workflowDock {
  top: var(--app-shell-inset);
  bottom: var(--app-shell-inset);
  left: var(--app-shell-inset);
  border-radius: var(--app-shell-radius);
}

/* The expanded dock visually locks onto the main shell instead of
   appearing like an unrelated floating card. */
.workflowDock:hover,
.workflowDock:focus-within {
  box-shadow:
    18px 0 64px rgba(0, 0, 0, 0.42),
    0 0 34px rgba(66, 245, 155, 0.065),
    0 0 0 1px rgba(255, 255, 255, 0.022) inset,
    0 1px 0 rgba(255, 255, 255, 0.055) inset;
}

/* Remove the visual gap between the collapsed dock and the content
   shell while retaining a slim breathing seam. */
@media (min-width: 1100px) {
  .app {
    grid-template-columns: 78px minmax(0, 1fr);
  }
}

/* Preserve the existing scroll fallback on shorter/smaller screens. */
@media (max-width: 1099px), (max-height: 719px) {
  .app {
    height: auto;
    min-height: 100dvh;
  }

  .appMain {
    height: auto;
    min-height: calc(100dvh - (var(--app-shell-inset) * 2));
    overflow: visible;
  }

  .appContent {
    height: auto;
    min-height: 100%;
    overflow: visible;
  }
}

