/* ============================================================
   Themed operational-formula tooltips
   The formula opens from the KPI value itself, not from a tiny
   hotspot on the surrounding card.
   ============================================================ */
.formulaMetricCard {
  position: relative;
  overflow: visible;
}

.metricValueFormulaTrigger {
  position: relative;
  width: max-content;
  max-width: 100%;
  outline: none;
  cursor: help;
}

.metricValueFormulaTrigger > strong {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: max-content;
  max-width: 100%;
  border-bottom: 1px dashed rgba(79, 215, 255, 0.42);
  transition:
    color 0.18s ease,
    border-color 0.18s ease,
    text-shadow 0.18s ease;
}

.metricValueFormulaTrigger > strong::after {
  content: "ƒ";
  display: inline-grid;
  place-items: center;
  width: 15px;
  height: 15px;
  border: 1px solid rgba(79, 215, 255, 0.28);
  border-radius: 50%;
  color: var(--cyan);
  background: rgba(79, 215, 255, 0.08);
  font-family: Georgia, serif;
  font-size: 9px;
  line-height: 1;
  opacity: 0.82;
}

.metricValueFormulaTrigger:hover > strong,
.metricValueFormulaTrigger:focus-visible > strong,
.metricValueFormulaTrigger:focus-within > strong {
  border-color: rgba(66, 245, 155, 0.9);
  text-shadow: 0 0 16px rgba(66, 245, 155, 0.28);
}

.metricFormulaTooltip {
  position: absolute;
  z-index: 140;
  left: 50%;
  bottom: calc(100% + 12px);
  width: min(350px, 38vw);
  padding: 12px 13px;
  border: 1px solid rgba(79, 215, 255, 0.28);
  border-radius: 15px;
  color: var(--text);
  background:
    radial-gradient(
      circle at 12% 0%,
      rgba(66, 245, 155, 0.16),
      transparent 55%
    ),
    linear-gradient(145deg, rgba(7, 29, 23, 0.98), rgba(6, 20, 21, 0.98));
  box-shadow:
    0 18px 46px rgba(0, 0, 0, 0.52),
    0 0 0 1px rgba(66, 245, 155, 0.06) inset,
    0 0 28px rgba(79, 215, 255, 0.1);
  backdrop-filter: blur(18px);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, 7px) scale(0.97);
  transform-origin: bottom center;
  transition:
    opacity 0.16s ease,
    transform 0.16s ease,
    visibility 0.16s ease;
}

.metricFormulaTooltip::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 12px;
  height: 12px;
  border-right: 1px solid rgba(79, 215, 255, 0.28);
  border-bottom: 1px solid rgba(79, 215, 255, 0.28);
  background: rgba(6, 20, 21, 0.98);
  transform: translateX(-50%) rotate(45deg);
}

.metricValueFormulaTrigger:hover .metricFormulaTooltip,
.metricValueFormulaTrigger:focus-visible .metricFormulaTooltip,
.metricValueFormulaTrigger:focus-within .metricFormulaTooltip {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0) scale(1);
}

.metricFormulaTooltip .metricFormulaLabel {
  display: inline-flex;
  width: max-content;
  margin: 0 0 8px;
  padding: 4px 7px;
  border: 1px solid rgba(66, 245, 155, 0.22);
  border-radius: 999px;
  color: var(--green);
  background: rgba(66, 245, 155, 0.08);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 8px;
  font-weight: 950;
}

.metricFormulaTooltip code {
  display: block;
  margin: 0 0 6px;
  color: #ddfff0;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 10.5px;
  font-weight: 750;
  line-height: 1.52;
  white-space: normal;
}

.metricFormulaTooltip code sub {
  color: var(--cyan);
  font-size: 0.72em;
}

.metricFormulaTooltip p {
  margin: 8px 0 0;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.075);
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.4;
}

/* Keep edge-card tooltips inside the dashboard viewport. */
.bottomInsightGrid > .formulaMetricCard:first-child .metricFormulaTooltip {
  left: 0;
  transform: translate(0, 7px) scale(0.97);
  transform-origin: bottom left;
}

.bottomInsightGrid
  > .formulaMetricCard:first-child
  .metricFormulaTooltip::after {
  left: 28px;
}

.bottomInsightGrid
  > .formulaMetricCard:first-child
  .metricValueFormulaTrigger:hover
  .metricFormulaTooltip,
.bottomInsightGrid
  > .formulaMetricCard:first-child
  .metricValueFormulaTrigger:focus-visible
  .metricFormulaTooltip,
.bottomInsightGrid
  > .formulaMetricCard:first-child
  .metricValueFormulaTrigger:focus-within
  .metricFormulaTooltip {
  transform: translate(0, 0) scale(1);
}

.bottomInsightGrid > .formulaMetricCard:last-child .metricFormulaTooltip {
  right: 0;
  left: auto;
  transform: translate(0, 7px) scale(0.97);
  transform-origin: bottom right;
}

.bottomInsightGrid
  > .formulaMetricCard:last-child
  .metricFormulaTooltip::after {
  right: 28px;
  left: auto;
  transform: rotate(45deg);
}

.bottomInsightGrid
  > .formulaMetricCard:last-child
  .metricValueFormulaTrigger:hover
  .metricFormulaTooltip,
.bottomInsightGrid
  > .formulaMetricCard:last-child
  .metricValueFormulaTrigger:focus-visible
  .metricFormulaTooltip,
.bottomInsightGrid
  > .formulaMetricCard:last-child
  .metricValueFormulaTrigger:focus-within
  .metricFormulaTooltip {
  transform: translate(0, 0) scale(1);
}

.bottomInsightGrid > .formulaMetricCard:hover,
.bottomInsightGrid > .formulaMetricCard:focus-within {
  z-index: 120;
}

@media (max-width: 1099px) {
  .metricFormulaTooltip,
  .bottomInsightGrid > .formulaMetricCard:first-child .metricFormulaTooltip,
  .bottomInsightGrid > .formulaMetricCard:last-child .metricFormulaTooltip {
    right: auto;
    left: 0;
    bottom: calc(100% + 10px);
    width: min(360px, calc(100vw - 48px));
    transform: translate(0, 7px) scale(0.97);
    transform-origin: bottom left;
  }

  .metricValueFormulaTrigger:hover .metricFormulaTooltip,
  .metricValueFormulaTrigger:focus-visible .metricFormulaTooltip,
  .metricValueFormulaTrigger:focus-within .metricFormulaTooltip,
  .bottomInsightGrid
    > .formulaMetricCard:first-child
    .metricValueFormulaTrigger:hover
    .metricFormulaTooltip,
  .bottomInsightGrid
    > .formulaMetricCard:first-child
    .metricValueFormulaTrigger:focus-visible
    .metricFormulaTooltip,
  .bottomInsightGrid
    > .formulaMetricCard:first-child
    .metricValueFormulaTrigger:focus-within
    .metricFormulaTooltip,
  .bottomInsightGrid
    > .formulaMetricCard:last-child
    .metricValueFormulaTrigger:hover
    .metricFormulaTooltip,
  .bottomInsightGrid
    > .formulaMetricCard:last-child
    .metricValueFormulaTrigger:focus-visible
    .metricFormulaTooltip,
  .bottomInsightGrid
