/* ============================================================
   Workspace Live Pipeline Telemetry
   Keeps the user on the Workspace while the solver runs, then
   reveals Results only after the execution trace completes.
   ============================================================ */

.workspaceChartStage {
  position: relative;
  isolation: isolate;
}

.workspaceTelemetryOverlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  padding: 12px;
  overflow: hidden;
  border-radius: inherit;
  background:
    radial-gradient(
      circle at 18% 10%,
      rgba(66, 245, 155, 0.12),
      transparent 38%
    ),
    linear-gradient(180deg, rgba(2, 10, 7, 0.76), rgba(2, 9, 7, 0.9));
  backdrop-filter: blur(8px) saturate(0.82);
  animation: workspaceTelemetryFadeIn 0.28s ease both;
}

.workspaceTelemetryOverlay::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(79, 215, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(79, 215, 255, 0.035) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, 0.82), transparent 96%);
}

@keyframes workspaceTelemetryFadeIn {
  from {
    opacity: 0;
    transform: scale(0.992);
  }
}

.workspaceTelemetryTerminal {
  position: relative;
  z-index: 1;
  width: min(94%, 980px);
  height: min(88%, 520px);
  min-height: 270px;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  overflow: hidden;
  border: 1px solid rgba(66, 245, 155, 0.34);
  border-radius: 20px;
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(79, 215, 255, 0.09),
      transparent 30%
    ),
    linear-gradient(180deg, rgba(3, 15, 11, 0.97), rgba(2, 10, 8, 0.98));
  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.58),
    0 0 0 1px rgba(66, 245, 155, 0.055) inset,
    0 0 42px rgba(66, 245, 155, 0.12);
}

.workspaceTelemetryHead,
.workspaceTelemetryFoot {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 11px 14px;
  background: rgba(255, 255, 255, 0.025);
}

.workspaceTelemetryHead {
  border-bottom: 1px solid rgba(192, 255, 218, 0.11);
}

.workspaceTelemetryHead > div:first-child {
  min-width: 0;
}

.workspaceTelemetryHead span,
.workspaceTelemetryHead strong,
.workspaceTelemetryHead small {
  display: block;
}

.workspaceTelemetryHead > div:first-child > span {
  margin-bottom: 3px;
  color: var(--green);
  text-transform: uppercase;
  letter-spacing: 0.13em;
  font-size: 8px;
  font-weight: 950;
}

.workspaceTelemetryHead strong {
  overflow: hidden;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 15px;
  letter-spacing: -0.025em;
}

.workspaceTelemetryHead small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.25;
}

.workspaceTelemetryStatus {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  border: 1px solid rgba(79, 215, 255, 0.17);
  border-radius: 999px;
  color: var(--cyan);
  background: rgba(79, 215, 255, 0.06);
}

.workspaceTelemetryStatus i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
