}

.workspaceTelemetryStatus span {
  color: inherit;
  text-transform: none;
  letter-spacing: 0;
  white-space: nowrap;
  font-size: 8px;
  font-weight: 900;
}

.workspaceTelemetryProgressBlock {
  display: grid;
  gap: 6px;
  padding: 8px 14px 9px;
  border-bottom: 1px solid rgba(192, 255, 218, 0.08);
  background: rgba(0, 0, 0, 0.12);
}

.workspaceTelemetryProgressBlock > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.workspaceTelemetryProgressBlock span {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 8px;
  font-weight: 900;
}

.workspaceTelemetryProgressBlock strong {
  color: var(--green);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
