.workspaceTelemetryFoot {
  border-top: 1px solid rgba(192, 255, 218, 0.1);
}

.workspaceTelemetryFoot span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 8px;
  font-weight: 800;
