    ),
    rgba(255, 255, 255, 0.032);
  box-shadow:
    0 0 0 1px rgba(79, 215, 255, 0.045) inset,
    0 10px 24px rgba(0, 0, 0, 0.17);
}

.decisionPreviewToggle {
  width: 100%;
  min-height: 61px;
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) 31px;
  align-items: center;
  gap: 9px;
  padding: 9px 9px 9px 10px;
  border: 0;
  border-radius: inherit;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.decisionPreviewToggle:hover,
.decisionPreviewToggle:focus-visible {
  filter: none;
  background: rgba(255, 255, 255, 0.025);
}

.decisionPreviewToggle:focus-visible {
  outline: 1px solid rgba(79, 215, 255, 0.7);
  outline-offset: -2px;
}

.decisionPreviewToggle .decisionStatusDot {
  align-self: center;
}

.decisionPreviewToggle .decisionPreviewCopy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.decisionPreviewToggle .decisionPreviewCopy > div {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 9px;
}

.decisionPreviewToggle .decisionPreviewCopy span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 8.5px;
  line-height: 1.15;
  letter-spacing: 0.045em;
}

.decisionPreviewToggle .decisionPreviewCopy strong {
  flex: 0 0 auto;
  margin: 0;
  color: inherit;
  white-space: nowrap;
  font-size: 10.5px;
  line-height: 1.15;
}

