/* ============================================================
   Cinematic full-screen telemetry + direct workflow handoff
   ============================================================ */

/* The execution trace now owns the entire viewport rather than being
   clipped inside the Workspace chart panel. */
.workspaceTelemetryOverlay.fullscreen {
  position: fixed;
  inset: 0;
  z-index: 320;
  width: 100vw;
  height: 100dvh;
  padding: clamp(22px, 5vh, 56px) clamp(24px, 6vw, 96px);
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background:
    radial-gradient(
      circle at 50% 42%,
      rgba(66, 245, 155, 0.105),
      transparent 35rem
    ),
    radial-gradient(
      circle at 84% 12%,
      rgba(79, 215, 255, 0.08),
      transparent 28rem
    ),
    linear-gradient(180deg, rgba(1, 8, 6, 0.88), rgba(0, 4, 3, 0.965));
  backdrop-filter: blur(13px) saturate(0.72);
  -webkit-backdrop-filter: blur(13px) saturate(0.72);
}

.workspaceTelemetryOverlay.fullscreen::before {
  background-size: 36px 36px;
  opacity: 0.78;
  mask-image: radial-gradient(circle at center, #000 18%, transparent 88%);
}

.workspaceTelemetryOverlay.fullscreen .workspaceTelemetryTerminal {
  width: min(1080px, calc(100vw - 96px));
