/* ============================================================
   Compact validation cards + wider control tower
   - Closed cards hug their content instead of stretching
   - Mathematical detail expands only after a click
   - Execution-flow helper removed from JSX
   - Wider sidebar gives formulas and status copy more room
   ============================================================ */

@media (min-width: 1100px) {
  .workspaceLayoutContainer {
    grid-template-columns: minmax(0, 1fr) clamp(390px, 27vw, 420px);
    gap: 12px;
  }

  .workspaceRightColumn.controlValidationTower {
    width: auto;
    min-width: 390px;
    max-width: 420px;
    padding: 11px;
  }
}

/* Keep the list pinned to the top. The panel may use the available
   sidebar height, but its closed cards must never divide that height. */
.towerDecisionList {
  flex: 1 1 auto;
  min-height: 0;
  display: flex !important;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  align-content: flex-start;
  gap: 8px;
  overflow-x: hidden;
  overflow-y: auto;
}

.towerDecisionList .decisionPreviewItem {
  flex: 0 0 auto !important;
  align-self: stretch;
  width: 100%;
  height: auto !important;
  min-height: 0 !important;
  max-height: none;
  display: block !important;
}

.decisionPreviewToggle {
  width: 100%;
  height: auto !important;
  min-height: 58px;
  padding: 10px 11px;
}

/* A closed body contributes exactly zero layout height. */
.decisionMathPanel[aria-hidden="true"] {
  grid-template-rows: 0fr !important;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  border-top-color: transparent;
  pointer-events: none;
}

.decisionPreviewItem.expanded .decisionMathPanel,
.decisionMathPanel[aria-hidden="false"] {
  grid-template-rows: 1fr !important;
  max-height: 560px;
  opacity: 1;
  visibility: visible;
  border-top-color: rgba(192, 255, 218, 0.1);
  pointer-events: auto;
}

.decisionMathInner {
  min-height: 0 !important;
}

/* With the helper flow removed, the launch action becomes the clean
   visual endpoint of the control tower. */
.towerLaunchZone {
  flex: 0 0 auto;
  display: block;
  margin-top: 0;
}

.towerLaunchZone .workspaceLaunch {
  width: 100%;
}

