/* ============================================================
   Validation Gate — programmatic snap viewport
   - Closed state: all five checks divide and fill the available gate
   - Open state: the selected card is moved to one fixed top position
   - User scrolling and the physical scrollbar are disabled
   ============================================================ */

.towerDecisionList {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden !important;
  padding-right: 0 !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none;
  overscroll-behavior: none;
  scroll-behavior: smooth;
}

.towerDecisionList::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* Resting view: the five validation cards consume the complete viewport. */
.towerDecisionList.allValidationClosed {
  display: grid !important;
  grid-template-columns: 1fr;
  grid-template-rows: repeat(5, minmax(0, 1fr));
  align-items: stretch;
  align-content: stretch;
  gap: 8px;
}

.towerDecisionList.allValidationClosed .decisionPreviewItem {
  align-self: stretch;
  width: 100%;
  height: 100% !important;
  min-height: 0 !important;
  max-height: none;
}

.towerDecisionList.allValidationClosed .decisionPreviewToggle {
  height: 100% !important;
  min-height: 0 !important;
  padding-top: 8px;
  padding-bottom: 8px;
}

.towerDecisionList.allValidationClosed .decisionSnapSpacer {
  display: none;
}

/* Inspection view: cards become natural-height rows. React moves the active
   card to scrollTop = its offset, so every metric opens at the same position. */
.towerDecisionList.hasExpandedValidation {
  display: flex !important;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  align-content: flex-start;
  gap: 8px;
}

.towerDecisionList.hasExpandedValidation .decisionPreviewItem {
  flex: 0 0 auto !important;
  align-self: stretch;
  width: 100%;
  height: auto !important;
  min-height: 0 !important;
}

.towerDecisionList.hasExpandedValidation .decisionPreviewToggle {
  height: auto !important;
  min-height: 58px;
}

/* Invisible runway: lets even the fifth card be snapped to the same top edge
   without exposing a scrollbar or allowing manual movement. */
.decisionSnapSpacer {
  flex: 0 0 100%;
  width: 1px;
  min-height: 100%;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

@media (min-width: 1100px) and (max-height: 820px) {
  .towerDecisionList.allValidationClosed {
    gap: 6px;
  }

  .towerDecisionList.hasExpandedValidation {
    gap: 6px;
  }

  .towerDecisionList.hasExpandedValidation .decisionPreviewToggle {
    min-height: 52px;
  }
}

/* Keep the existing responsive card grid on tablet/mobile. */
@media (max-width: 1099px) {
  .towerDecisionList,
  .towerDecisionList.allValidationClosed,
  .towerDecisionList.hasExpandedValidation {
