/* ============================================================
   Cinematic result-tab transition
   Old evidence slides away, the remaining rail is covered by a
   deep-green curtain, then the next tab is revealed.
   ============================================================ */

.resultsTabTakeaway {
  position: relative;
  transform: translateZ(0);
}

/* Exit: the current left evidence panel slides toward the selected direction. */

/* The new tab is mounted while the green curtain is at maximum opacity. */

/* Give the left panel a brighter green electrical surface during the hand-off. */

/* The right-hand remainder becomes deep green, never pure black. */
.resultsTabTakeaway {
  overflow: hidden;
}

.resultsTakeawayContent {
  position: relative;
  z-index: 1;
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 7px;
  opacity: 1;
  filter: blur(0) saturate(1);
  transform: scale(1);
  transition:
    opacity 220ms ease,
    filter 280ms ease,
    transform 320ms cubic-bezier(0.22, 1, 0.36, 1);
}

.resultsTabGreenCurtain {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  border-radius: inherit;
  opacity: 0;
  background:
    radial-gradient(
      circle at 10% 50%,
      rgba(20, 125, 86, 0.42),
      transparent 46%
    ),
    linear-gradient(118deg, rgba(2, 36, 27, 0.94), rgba(2, 24, 18, 0.985));
  border: 1px solid rgba(34, 166, 112, 0.22);
  box-shadow:
    inset 0 0 54px rgba(2, 58, 41, 0.68),
    inset 18px 0 46px rgba(20, 125, 86, 0.13),
    0 0 30px rgba(0, 18, 13, 0.34);
  backdrop-filter: blur(2px) saturate(0.72);
  transition: opacity 210ms ease;
}

/* A narrow illuminated seam separates the moving evidence from the dimmed rail. */

@media (prefers-reduced-motion: reduce) {
  .resultsTakeawayContent,
  .resultsTabGreenCurtain {
    transition: none !important;
    animation: none !important;
  }
}

/* ============================================================
   Workflow slit — deep-green contrast field
   Preserves the original beam/message animation. The dimmer is a
   full-screen underlay, while the original slit stays above it.
   ============================================================ */
.workflowSplitTransition {
  --workflow-slit-width: max(360px, min(46vw, 560px));
  isolation: isolate;
}

.workflowSplitDimmer {
  position: absolute;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(circle at 0% 50%, rgba(20, 118, 82, 0.2), transparent 34%),
    linear-gradient(112deg, rgba(2, 38, 29, 0.92), rgba(1, 18, 14, 0.975));
  box-shadow:
    inset 0 0 110px rgba(2, 74, 52, 0.2),
    inset 0 0 110px rgba(0, 8, 6, 0.4);
  backdrop-filter: blur(1.5px) saturate(0.72);
  -webkit-backdrop-filter: blur(1.5px) saturate(0.72);
  animation: workflowSplitDimmer 0.56s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Keep the existing slit and its copy above the new contrast field. */
.workflowSplitBeam {
  z-index: 2;
  width: var(--workflow-slit-width);
}

.workflowSplitMessage {
  z-index: 3;
}

@keyframes workflowSplitDimmer {
  0% {
    opacity: 0;
  }

  12% {
    opacity: 0.18;
  }

  25%,
  68% {
    opacity: 1;
  }

  82% {
    opacity: 0.72;
  }

  100% {
    opacity: 0;
  }
}

@media (max-width: 760px) {
  .workflowSplitTransition {
    --workflow-slit-width: min(86vw, 460px);
  }
}

@media (max-width: 480px) {
  .workflowSplitTransition {
    --workflow-slit-width: 92vw;
  }
}

@media (prefers-reduced-motion: reduce) {
  .workflowSplitDimmer {
    animation-duration: 0.01ms !important;
  }
}

/* ============================================================
   Workflow transition refinement — zero seam + slower pacing
   The contrast field is fully opaque at its peak and matches the
   slit color around the moving polygon tip, so the old page cannot
   appear as a vertical/triangular gap.
   ============================================================ */
.workflowSplitTransition {
  animation-duration: 1.1s !important;
}

.workflowSplitDimmer {
  /* Match the beam until slightly beyond its animated tip, then
     transition into the brighter deep-green contrast field. */
  background: linear-gradient(
    90deg,
    #020d09 0,
    #020d09 calc(var(--workflow-slit-width) + 34px),
    #02251b calc(var(--workflow-slit-width) + 150px),
    #01150f 72%,
    #010f0c 100%
  ) !important;
  box-shadow:
    inset 0 0 120px rgba(5, 88, 61, 0.18),
    inset 0 0 150px rgba(0, 8, 6, 0.34) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  animation: workflowSplitDimmerSlow 1.1s cubic-bezier(0.22, 1, 0.36, 1) both !important;
}

.workflowSplitBeam {
  animation-duration: 1.1s !important;
}

.workflowSplitMessage {
  animation-duration: 1.1s !important;
}

@keyframes workflowSplitDimmerSlow {
  0% {
    opacity: 0;
  }

  8% {
    opacity: 1;
  }

  76% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

/* Slow the shell/beam/copy phases as well instead of only stretching
   the dimmer. This preserves the original slit choreography. */
@keyframes workflowSplitShell {
  0%,
  100% {
    opacity: 0;
  }
  8%,
  82% {
    opacity: 1;
  }
}

@keyframes workflowSplitBeam {
  0% {
    opacity: 0;
    transform: translateX(-100%) scaleX(0.46);
  }

  24%,
  72% {
    opacity: 1;
    transform: translateX(0) scaleX(1);
  }

  100% {
    opacity: 0;
    transform: translateX(-16%) scaleX(0.8);
  }
}

@keyframes workflowSplitCopy {
  0%,
  16% {
    opacity: 0;
    transform: translate(-15px, -50%);
  }

  30%,
  72% {
    opacity: 1;
    transform: translate(0, -50%);
  }

  100% {
    opacity: 0;
    transform: translate(13px, -50%);
  }
}

/* ============================================================
   Final workflow transition pass
   - fully opaque deep-green field: no old-page seam can show
   - slower 1.45 s choreography
   - slit remains the original polygon and sits above the field
   ============================================================ */
.workflowSplitTransition {
  animation-duration: 1.24s !important;
}

.workflowSplitDimmer {
  inset: 0 !important;
  opacity: 0;
  background: radial-gradient(
    circle at 76% 46%,
