  animation: workflowSplitDimmerFinal 1.24s cubic-bezier(0.22, 1, 0.36, 1) both !important;
}

.workflowSplitBeam,
.workflowSplitMessage {
  animation-duration: 1.24s !important;
}

@keyframes workflowSplitDimmerFinal {
  0% {
    opacity: 0;
  }

  6% {
    opacity: 1;
  }

  80% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

@keyframes workflowSplitShell {
  0%,
  100% {
    opacity: 0;
  }

  5%,
  86% {
    opacity: 1;
  }
}

@keyframes workflowSplitBeam {
  0% {
    opacity: 0;
    transform: translateX(-100%) scaleX(0.46);
  }

  25%,
  76% {
    opacity: 1;
    transform: translateX(0) scaleX(1);
  }

  100% {
