}

/* ============================================================
   Telemetry → Results handoff: deep-green blackout bridge
   The bridge keeps the dramatic full-screen pause, but replaces
   pure black with the same emerald field used by the 03 slit.
   ============================================================ */

.pipelineHandoffVeil {
  position: fixed;
  z-index: 230;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    circle at 76% 46%,
    #05271d 0%,
    #021c15 34%,
    #011710 66%,
    #01130e 100%
  );
  box-shadow:
    inset 0 0 150px rgba(6, 85, 61, 0.16),
    inset 0 0 190px rgba(0, 7, 5, 0.28);
  will-change: opacity;
  transition: opacity 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.pipelineHandoffVeil.cover,
.pipelineHandoffVeil.blend {
  opacity: 1;
}

.pipelineHandoffVeil.reveal {
  opacity: 0;
  transition-duration: 360ms;
}

/* During the handoff, the telemetry layer moves below the original workflow
   slit. Its terminal disappears into an opaque green surface instead of
   being abruptly unmounted against a different background. */
.workspaceTelemetryOverlay.fullscreen.handoff {
  z-index: 235;
  background: radial-gradient(
    circle at 76% 46%,
    #05271d 0%,
    #021c15 34%,
    #011710 66%,
    #01130e 100%
  ) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  transition:
    background 220ms ease,
    filter 220ms ease;
}

.workspaceTelemetryOverlay.fullscreen.handoff::before {
  opacity: 0;
  transition: opacity 180ms ease;
}

.workspaceTelemetryOverlay.fullscreen .workspaceTelemetryTerminal {
  transition:
    opacity 230ms ease,
    transform 260ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 230ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.workspaceTelemetryOverlay.fullscreen.handoff .workspaceTelemetryTerminal {
  opacity: 0;
  transform: translateY(-8px) scale(0.982);
  filter: blur(4px) saturate(0.55);
  border-color: rgba(66, 245, 155, 0.08);
  box-shadow: 0 24px 90px rgba(0, 0, 0, 0.28);
}

/* The existing slit stays above the handoff veil. */
.workflowSplitTransition {
  z-index: 240;
}

@media (prefers-reduced-motion: reduce) {
  .pipelineHandoffVeil,
  .workspaceTelemetryOverlay.fullscreen .workspaceTelemetryTerminal,
  .workspaceTelemetryOverlay.fullscreen.handoff::before {
    transition: none !important;
  }
}

