/* ============================================================
   Global top layer for Page 02 popovers / formula tooltips
   The scenario panel owns a backdrop-filter stacking context, so
   raising only the tooltip itself is insufficient. Raise the whole
   dashboard context and keep every intermediate ancestor unclipped.
   ============================================================ */
.workspaceLeftMain.launchpadMain,
.dashboardSection.launchpadDashboard,
.workspaceV2Dashboard.launchpadDashboard,
.bottomInsightGrid.fourStateSummary {
  position: relative;
  overflow: visible !important;
}

/* Dashboard must sit above the scenario panel while one of its
   interactive overlays is visible. The normal panels do not overlap,
   so keeping this layer above the scenario picker has no visual cost. */
.launchpadScenarioPanel {
  z-index: 20;
}

.launchpadDashboard {
  z-index: 200 !important;
  isolation: auto;
}

/* Raise the complete card, not only the absolutely-positioned child.
   This lets the tooltip escape sibling cards and all earlier rows. */
.fullControlGrid .featureControlCard:hover,
.fullControlGrid .featureControlCard:focus-within,
.bottomInsightGrid > .formulaMetricCard:hover,
.bottomInsightGrid > .formulaMetricCard:focus-within {
  position: relative;
  z-index: 2147483000 !important;
  overflow: visible !important;
}

.metricValueFormulaTrigger,
.featureFormulaTrigger {
  isolation: isolate;
}

.metricFormulaTooltip,
.featureFormulaTooltip,
.commitmentDecisionFormulaTooltip,
.readinessWhyPopover,
.solverStrategyPopover,
.advancedScenarioPopover {
  z-index: 2147483647 !important;
}

/* The 24h card used to hide its decorative background with overflow.
   Keep the formula layer free while clipping only decorative pseudo
   content through its own geometry. */
.commitmentDecisionCard.formulaMetricCard {
  overflow: visible !important;
}

