  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.commitmentCell {
  position: relative;
  height: 24px;
  border-radius: 5px;
  transition:
    filter 0.16s ease,
    transform 0.16s ease;
}

.commitmentCell:hover {
  z-index: 2;
  filter: brightness(1.18);
  transform: translateY(-1px);
}

.commitmentCell.off {
  border: 1px solid rgba(255, 255, 255, 0.045);
  background: rgba(255, 255, 255, 0.045);
}

.commitmentCell.on {
  border: 1px solid rgba(66, 245, 155, 0.36);
  background: linear-gradient(
    180deg,
    rgba(66, 245, 155, 0.88),
    rgba(42, 199, 127, 0.66)
  );
  box-shadow: 0 0 10px rgba(66, 245, 155, 0.12);
}

.commitmentCell.stress::after {
  content: "";
  position: absolute;
  inset: -3px -1px;
  z-index: -1;
  border-radius: 6px;
  background: rgba(255, 209, 102, 0.09);
}

.commitmentEvent {
  position: absolute;
  z-index: 3;
  top: -4px;
  left: -3px;
  width: 7px;
  height: 7px;
  border: 2px solid #06110d;
  border-radius: 50%;
}

