/* Full-screen supporting evidence modal */

.methodModalBackdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(0, 7, 5, 0.83);
  backdrop-filter: blur(14px);
  animation: operatorModalFade 0.18s ease both;
}

@keyframes operatorModalFade {
  from {
    opacity: 0;
  }
}

.methodModal {
  width: min(1240px, 96vw);
