  grid-template-rows: auto auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgba(66, 245, 155, 0.3);
  border-radius: 27px;
  background:
    radial-gradient(
      circle at 86% 4%,
      rgba(79, 215, 255, 0.11),
      transparent 25rem
    ),
    linear-gradient(145deg, #071811, #0b2119 58%, #081711);
  box-shadow: 0 40px 130px rgba(0, 0, 0, 0.64);
  animation: operatorModalRise 0.24s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes operatorModalRise {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.985);
  }
}

.methodModalHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
}

