  overflow: auto;
}

.methodModalBody > .finalReportPanel,
.methodModalBody > .breakdownChart,
.methodModalBody > .methodConvergencePanel {
  width: 100%;
  height: 100%;
  min-height: 500px;
}

.methodModalBody .finalReportPanel {
  height: 100%;
}

.methodModalBody .focusedQaoaConvergencePanel,
.methodModalBody .focusedQaoaChart {
  min-height: 500px;
}

@media (max-width: 1180px) {
