/* #region 04 — Popup layers, shell revisions, and result evidence views */
/* ============================================================
   Popup layer system v26
   Render full overlays and critical popovers above every page/card
   stacking context, and prevent anchored helpers from being clipped.
   ============================================================ */

:root {
  --layer-nav: 100;
  --layer-popover: 20000;
  --layer-modal-backdrop: 30000;
  --layer-modal: 30001;
  --layer-tooltip: 40000;
}

.nav {
  z-index: var(--layer-nav);
}

/* Portal overlays are direct children of body, so backdrop-filter,
   transforms, grid overflow, and isolated cards cannot trap them. */
.portalOverlayLayer,
.methodModalBackdrop,
.operatorDetailBackdrop {
  position: fixed !important;
  inset: 0 !important;
  z-index: var(--layer-modal-backdrop) !important;
  isolation: isolate;
}

.methodModal,
.operatorDetailModal {
  position: relative;
  z-index: var(--layer-modal) !important;
}

/* Generator details are a lightweight portal popover rather than a
   child of the scrollable timeline. */
.portalUnitPopover,
.unitSchedulePopover.portalUnitPopover {
  position: fixed !important;
  z-index: var(--layer-popover) !important;
  top: 92px !important;
  right: 24px !important;
  bottom: auto !important;
  left: auto !important;
  width: min(380px, calc(100vw - 48px)) !important;
  max-height: calc(100vh - 116px);
  overflow-y: auto;
  isolation: isolate;
}

/* Chart tooltip is portalled to body and uses viewport coordinates. */
.portalChartTooltip,
.chartHoverTooltip.portalChartTooltip {
  position: fixed !important;
  z-index: var(--layer-tooltip) !important;
  margin: 0;
  pointer-events: none;
  isolation: isolate;
}

/* Keep all anchored Page 02 helper popups above their surrounding
   cards and release every ancestor that previously clipped them. */
.workspaceViewport:has(.compoundReadinessPopover.open),
.workspaceLayoutContainer:has(.compoundReadinessPopover.open),
.workspaceRightColumn:has(.compoundReadinessPopover.open),
.singleLaunchFooter:has(.compoundReadinessPopover.open),
.singleOptimizationCompound:has(.compoundReadinessPopover.open) {
  position: relative;
  z-index: var(--layer-popover) !important;
  overflow: visible !important;
}

.workspaceViewport:has(.launchReadinessHelp:hover),
.workspaceLayoutContainer:has(.launchReadinessHelp:hover),
.workspaceRightColumn:has(.launchReadinessHelp:hover),
.singleLaunchFooter:has(.launchReadinessHelp:hover),
.singleOptimizationCompound:has(.launchReadinessHelp:hover),
.workspaceViewport:has(.launchReadinessHelp:focus-visible),
.workspaceLayoutContainer:has(.launchReadinessHelp:focus-visible),
.workspaceRightColumn:has(.launchReadinessHelp:focus-visible),
.singleLaunchFooter:has(.launchReadinessHelp:focus-visible),
.singleOptimizationCompound:has(.launchReadinessHelp:focus-visible) {
  overflow: visible !important;
}

.compoundReadinessPopover,
.readinessWhyPopover,
.solverStrategyPopover,
.advancedScenarioPopover,
.metricFormulaTooltip,
.featureFormulaTooltip,
.commitmentDecisionFormulaTooltip,
.compactWeatherProfilePopover {
  z-index: var(--layer-popover) !important;
}

/* Local columns remain clipped during normal use, but an open legacy
   inline popup can escape while transitioning to the portal layer. */
.scheduleColumn:has(.unitSchedulePopover),
.scheduleColumn:has(.unitSchedulePopover) .operatorScheduleBody,
.scheduleColumn:has(.unitSchedulePopover) .unitActionsScheduleView,
.operatorScheduleSection:has(.unitSchedulePopover) {
  overflow: visible !important;
  z-index: calc(var(--layer-popover) - 1) !important;
}

@media (max-width: 720px) {
  .portalUnitPopover,
  .unitSchedulePopover.portalUnitPopover {
    top: auto !important;
    right: 12px !important;
    bottom: 12px !important;
    left: 12px !important;
    width: auto !important;
    max-height: min(72vh, 620px);
  }

