/* ============================================================
   Page 02 v73 — metric values are the System Check interactions
   - Removes the seven separate information buttons
   - Dashed value underline communicates help affordance
   - Hover/focus/click popovers stay inside the System Check card
   ============================================================ */

.unifiedValidationGate .validationPopupList {
  position: relative;
  z-index: 1;
  overflow: visible !important;
}

.unifiedValidationGate .validationPopupList:has(.metricPopoverOpen) {
  z-index: 240;
}

.unifiedValidationGate .validationPopupCard {
  grid-template-columns: 8px minmax(0, 1fr) !important;
  overflow: visible !important;
  cursor: default;
}

.unifiedValidationGate .validationPopupCard.metricPopoverOpen {
  z-index: 260;
}

/* Only the value is interactive; the row itself remains visually quiet. */
.unifiedValidationGate .validationPopupCard:hover,
.unifiedValidationGate .validationPopupCard:focus-within {
  background: transparent !important;
}

.unifiedValidationGate .validationPopupCopy > div {
  overflow: visible;
}

.unifiedValidationGate .validationPopupCopy > small,
.unifiedValidationGate .validationCommitmentList .validationPopupCopy small {
  display: none !important;
}

.validationMetricInteraction {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

.validationMetricInteraction.open {
  z-index: 280;
}

.unifiedValidationGate .validationMetricValue {
  appearance: none;
  display: inline-block;
  max-width: 145px;
  margin: 0;
  padding: 1px 0 3px;
  overflow: hidden;
  border: 0;
  border-bottom: 1px dashed rgba(120, 255, 215, 0.45);
  border-radius: 0;
  outline: 0;
  color: var(--green);
  background: transparent;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
  font: inherit;
  font-size: 10.2px;
  font-weight: 900;
  line-height: 1;
  cursor: help;
  transition:
    color 140ms ease,
    border-color 140ms ease,
    text-shadow 140ms ease;
}

.unifiedValidationGate .validationMetricValue.metric-value--watch {
  color: var(--gold);
  border-bottom-color: rgba(255, 209, 102, 0.56);
}

.unifiedValidationGate .validationMetricValue.metric-value--risk {
  color: var(--red);
  border-bottom-color: rgba(255, 70, 120, 0.68);
}

.unifiedValidationGate .validationMetricValue:hover,
.unifiedValidationGate .validationMetricValue:focus-visible,
.validationMetricInteraction.open .validationMetricValue {
  border-bottom-color: currentColor;
  text-shadow: 0 0 10px color-mix(in srgb, currentColor 42%, transparent);
}

.unifiedValidationGate .validationMetricValue:focus-visible {
  outline: 1px solid color-mix(in srgb, currentColor 48%, transparent);
  outline-offset: 4px;
  border-radius: 3px;
}

.validationMetricPopover {
  position: absolute;
  right: -1px;
  z-index: 300;
  width: clamp(240px, 18vw, 272px);
  max-width: calc(100vw - 42px);
  max-height: 238px;
  display: grid;
  gap: 8px;
  padding: 11px;
  overflow-y: auto;
  border: 1px solid rgba(79, 215, 255, 0.2);
  border-radius: 13px;
  color: var(--text);
  background:
    radial-gradient(circle at 100% 0%, rgba(79, 215, 255, 0.1), transparent 155px),
    linear-gradient(150deg, rgba(5, 31, 23, 0.985), rgba(4, 21, 17, 0.99));
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.38);
  backdrop-filter: blur(16px);
  opacity: 1;
  transform: translateY(0);
  transform-origin: top right;
  animation: validationMetricPopoverIn 140ms ease both;
  scrollbar-width: thin;
  scrollbar-color: rgba(79, 215, 255, 0.34) transparent;
}

.validationMetricPopover.down {
  top: calc(100% + 8px);
}

.validationMetricPopover.up {
  bottom: calc(100% + 8px);
  transform-origin: bottom right;
}

.validationMetricPopover::-webkit-scrollbar {
  width: 4px;
}

.validationMetricPopover::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(79, 215, 255, 0.34);
}

@keyframes validationMetricPopoverIn {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
}

.validationMetricPopover.up {
  animation-name: validationMetricPopoverInUp;
}

@keyframes validationMetricPopoverInUp {
  from {
    opacity: 0;
    transform: translateY(-5px);
  }
}

