/* #endregion */

/* #region 06 — Global visual/layer lock and Workspace v85–v94 */
/* ============================================================
   v85 — global layer audit and stacking-context contract
   Applies to Home, Workspace, Results, all tabs, drawers, popovers,
   chart tooltips, unit details, evidence modals, and loading overlays.
   ============================================================ */

:root {
  --z-page: 0;
  --z-card: 10;
  --z-nav: 100;
  --z-inline-popover: 600;
  --z-portal-popover: 900;
  --z-portal-tooltip: 1000;
  --z-drawer-backdrop: 2000;
  --z-drawer: 2010;
  --z-modal-backdrop: 3000;
  --z-modal: 3010;
  --z-blocking-overlay: 5000;
}

/* Every route owns one predictable local stacking context. */
.app > main,
.homeGrid,
.workspaceViewport,
.results,
.resultsViewport,
.operatorDecisionBoard,
.plainOperatorBoard {
  position: relative;
  z-index: var(--z-page);
  isolation: isolate;
}

.nav {
  z-index: var(--z-nav) !important;
}

/* Ordinary cards never compete with floating UI. */
.panel,
.scenarioHorizontalSection,
.dashboardSection,
.workspaceRightColumn,
.preOptimizationPanel,
.operationalStressPanel,
.unifiedValidationGate,
.mainOperatorDispatchPanel,
.actionLogPanel,
.resultTableCard,
.insightPanel,
.finalConclusionCard {
  z-index: auto;
}

/* ---------------- Workspace inline controls ---------------- */
.launchpadScenarioPanel,
.launchpadDashboard,
.workspaceRightColumn.controlValidationTower,
.singleLaunchFooter,
.singleOptimizationCompound {
  position: relative;
}

.launchpadScenarioPanel {
  z-index: var(--z-card) !important;
}

.launchpadDashboard,
.workspaceRightColumn.controlValidationTower {
  z-index: var(--z-page) !important;
}

.launchpadScenarioPanel.profileMenuOpen {
  z-index: var(--z-inline-popover) !important;
  overflow: visible !important;
}

.compactWeatherProfileSelector,
.compactWeatherProfilePopover {
  z-index: calc(var(--z-inline-popover) + 1) !important;
}

.compoundReadinessPopover,
.readinessWhyPopover,
.solverStrategyPopover,
.advancedScenarioPopover,
.metricFormulaTooltip,
.featureFormulaTooltip,
.commitmentDecisionFormulaTooltip {
  z-index: var(--z-inline-popover) !important;
}

/* The System Check card clips its own visual surface. Its metric
   explanations are portalled to body, so no child needs to escape. */
.controlValidationTower .unifiedValidationGate {
  position: relative;
  z-index: var(--z-card) !important;
  isolation: isolate;
  overflow: hidden !important;
}

.unifiedValidationGate .validationPopupList,
.unifiedValidationGate .validationPopupCard,
.unifiedValidationGate .validationPopupCopy,
.unifiedValidationGate .validationMetricInteraction {
  z-index: auto !important;
}

.unifiedValidationGate .validationPopupList,
.unifiedValidationGate .validationPopupCard {
  overflow: visible !important;
}

/* ---------------- Portalled System Check metric popover ---------------- */
.portalValidationMetricPopover.validationMetricPopover {
  position: fixed !important;
  right: auto !important;
  bottom: auto !important;
  z-index: var(--z-portal-popover) !important;
  margin: 0 !important;
  overflow-x: hidden;
  overflow-y: auto;
  isolation: isolate;
  transform: none !important;
  transform-origin: center !important;
  animation: validationPortalPopoverIn 140ms ease both !important;
}

@keyframes validationPortalPopoverIn {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.portalValidationMetricPopover .validationMetricPopoverHeader {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 7px;
  border-bottom: 1px solid rgba(192, 255, 218, 0.09);
}

.portalValidationMetricPopover .validationMetricPopoverHeader span {
  min-width: 0;
  overflow: hidden;
  color: rgba(225, 255, 241, 0.92);
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 7.4px;
  font-weight: 950;
}

.portalValidationMetricPopover .validationMetricPopoverHeader strong {
  flex: 0 0 auto;
  margin: 0;
  color: var(--green);
  font-size: 9.5px;
  line-height: 1.1;
}

.portalValidationMetricPopover.watch .validationMetricPopoverHeader strong {
  color: var(--gold);
}

.portalValidationMetricPopover.risk .validationMetricPopoverHeader strong {
  color: var(--red);
}

.portalValidationMetricPopover .validationMetricPopoverExplanation {
  margin: 0;
  color: rgba(155, 188, 173, 0.78);
  font-size: 7.8px;
  line-height: 1.42;
}

.portalValidationMetricPopover .validationMetricPopoverSection {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.portalValidationMetricPopover .validationMetricPopoverSection > span {
  color: var(--cyan);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 6.5px;
  font-weight: 950;
}

.portalValidationMetricPopover .validationMetricPopoverSection.current {
  padding: 7px 8px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
}

.portalValidationMetricPopover .validationMetricPopoverSection.current > strong {
  margin: 0;
  color: var(--text);
  white-space: normal;
  font-size: 7.8px;
  font-weight: 750;
  line-height: 1.38;
}

.portalValidationMetricPopover .validationMetricPopoverSection.formula > div {
  min-width: 0;
}

.portalValidationMetricPopover .decisionFormulaExpression {
  min-height: 0;
  margin: 0;
  padding: 8px;
  border: 1px solid rgba(79, 215, 255, 0.13);
  border-radius: 9px;
  color: #e9fff5;
  background: rgba(79, 215, 255, 0.035);
  white-space: normal;
  font-size: 8px;
  line-height: 1.35;
}

.portalValidationMetricPopover .decisionFormulaExpression span {
  overflow: visible;
  color: inherit;
  text-overflow: clip;
  white-space: normal;
  text-transform: none;
  letter-spacing: 0;
  font-size: inherit;
  font-weight: 700;
}

.portalValidationMetricPopover .validationMetricPopoverSection.threshold p {
  margin: 0;
  color: rgba(155, 188, 173, 0.76);
  font-size: 7.4px;
  line-height: 1.4;
}

/* ---------------- Results / chart floating content ---------------- */
.portalUnitPopover,
.unitSchedulePopover.portalUnitPopover {
  z-index: var(--z-portal-popover) !important;
}

.portalChartTooltip,
.chartHoverTooltip.portalChartTooltip {
  z-index: var(--z-portal-tooltip) !important;
}

/* Non-portalled chart helpers stay inside their own chart cards. */
.costDonutTooltip,
.convergenceHoverTooltip,
.threeCostLineTooltip,
.chartComputeOverlay,
.chartRevealOverlay {
  z-index: 30 !important;
}

.costBreakdownChart,
.qaoaConvergencePanel,
.dispatchChart,
.mainOperatorDispatchPanel {
  position: relative;
  isolation: isolate;
}

/* Unit schedule body and Action Log clip ordinary content. The selected
   unit details use a body portal and therefore remain visible safely. */
.scheduleColumn,
.operatorScheduleBody,
.unitActionsScheduleView,
.actionLogPanel,
.actionLogBody {
  isolation: isolate;
}

.scheduleColumn,
.operatorScheduleBody,
.unitActionsScheduleView {
  overflow: hidden;
}

/* ---------------- Drawers and true modals ---------------- */
.weatherProfileDrawerLayer {
  position: fixed !important;
  inset: 0 !important;
  z-index: var(--z-drawer-backdrop) !important;
  isolation: isolate;
}

.weatherProfileDrawer {
  z-index: var(--z-drawer) !important;
}

.portalOverlayLayer,
.methodModalBackdrop,
.operatorDetailBackdrop {
  position: fixed !important;
  inset: 0 !important;
  z-index: var(--z-modal-backdrop) !important;
  isolation: isolate;
}

.methodModal,
.operatorDetailModal {
  position: relative;
  z-index: var(--z-modal) !important;
  isolation: isolate;
}

/* The full-screen optimizer telemetry is the only blocking layer and
   therefore always sits above dropdowns, drawers, tooltips, and modals. */
.workspaceTelemetryOverlay.fullscreen,
.workspaceTelemetryOverlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: var(--z-blocking-overlay) !important;
  isolation: isolate;
}

/* Remove legacy extreme z-index escalation now that the layer scale is
   explicit. These selectors previously produced cross-page bleed. */
.fullControlGrid .featureControlCard:hover,
.fullControlGrid .featureControlCard:focus-within,
.bottomInsightGrid > .formulaMetricCard:hover,
.bottomInsightGrid > .formulaMetricCard:focus-within {
  z-index: 2 !important;
}

/* Responsive overlays preserve the same order. */
@media (max-width: 1099px) {
  .portalValidationMetricPopover.validationMetricPopover {
    width: min(272px, calc(100vw - 28px)) !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .portalValidationMetricPopover.validationMetricPopover {
    animation: none !important;
  }
}

/* Neutralize legacy :has() escalation from the former inline readiness
   popup. It must never lift an entire page above drawers or modals. */
.workspaceViewport:has(.compoundReadinessPopover.open),
.workspaceLayoutContainer:has(.compoundReadinessPopover.open),
.workspaceRightColumn:has(.compoundReadinessPopover.open),
.singleLaunchFooter:has(.compoundReadinessPopover.open),
.singleOptimizationCompound:has(.compoundReadinessPopover.open) {
  z-index: auto !important;
}

.singleLaunchFooter:has(.compoundReadinessPopover.open) {
  z-index: var(--z-inline-popover) !important;
}

/* ============================================================
   v86 — Dark Teal Control Room
   A single visual language for UI interaction, semantic status,
   and physical-system data across Home, Workspace, Results, drawers,
   charts, and modals. Layout and behavior are unchanged.
   ============================================================ */

:root {
  /* Neutral teal surfaces */
  --bg: #031a17;
  --bg-2: #041f1b;
  --panel: #06251f;
  --panel-2: #092e27;
  --surface-hover: #0c3930;
  --soft: rgba(145, 175, 167, 0.055);
  --soft-2: rgba(145, 175, 167, 0.09);
  --line: #184b40;
  --line-strong: #24705f;

  /* Typography */
  --text: #ecf8f4;
  --muted: #91afa7;
  --muted-2: #63847b;
  --disabled: #47665e;

  /* UI interaction */
  --primary-action: #00e6c3;
  --primary-highlight: #17d6ff;
  --focus-ring: rgba(0, 230, 195, 0.3);

  /* Semantic status */
  --success: #25d98a;
  --info: #22d3ee;
  --warning: #f6c85f;
  --risk: #ff4d78;
  --critical: #ff365e;
  --neutral: #314f48;

  /* Backward-compatible aliases */
  --green: var(--success);
  --cyan: var(--info);
  --gold: var(--warning);
  --red: var(--risk);
  --blue: #8c9eff;

  /* Physical-data palette */
  --data-load: #ffd166;
  --data-solar: #f6c85f;
  --data-wind: #8c9eff;
  --data-renewable: #18e3a0;
  --data-battery: #c05cfa;
  --data-grid: #16c9e8;
  --data-diesel: #ff6754;
  --data-residual: #ff3f6c;
  --data-grid-limit: #18bfe3;
  --data-stress-window: rgba(246, 200, 95, 0.1);

  --shadow: 0 16px 42px rgba(0, 0, 0, 0.24);
}

/* ---------- Background and surfaces ---------- */
body {
  color: var(--text);
  background:
    radial-gradient(circle at 12% 8%, rgba(0, 230, 195, 0.055), transparent 28rem),
    radial-gradient(circle at 88% 5%, rgba(23, 214, 255, 0.04), transparent 25rem),
    linear-gradient(145deg, #021512, var(--bg) 46%, #041d19);
}

.appMain,
.nav,
.workflowDock {
  border-color: var(--line) !important;
  background-color: var(--bg) !important;
}

.panel,
.conclusion,
.winnerCard,
.chartPanel,
.resultTablePanel,
.scenarioHorizontalSection,
.dashboardSection,
.workspaceRightColumn,
.railOperatingInputs,
.unifiedValidationGate,
.preOptimizationPanel,
.operationalStressPanel,
.methodModal,
.weatherProfileDrawer,
.resultKpiCard,
.insightPanel,
.resultTableCard,
.finalConclusionCard,
.actionLogPanel,
.scheduleColumn,
.mainOperatorDispatchPanel,
.operatorDetailModal {
  border-color: var(--line) !important;
  background:
    linear-gradient(145deg, rgba(6, 37, 31, 0.97), rgba(9, 46, 39, 0.93)) !important;
  box-shadow: var(--shadow) !important;
}

/* Nested / secondary surfaces */
.primaryScenarioCard,
.solverCompactCard,
.featureControlCard,
.validationPopupCard,
.compactWeatherProfileOption,
.insightItem,
.breakdownColumn,
.svgChartWrap,
.dispatchBarFrame,
.bitstringBox,
.bitstringShowcase,
.costDonutTooltip,
.threeCostLineTooltip,
.convergenceHoverTooltip,
.chartHoverTooltip,
.portalValidationMetricPopover,
.portalUnitPopover {
  border-color: var(--line) !important;
  background-color: var(--panel-2) !important;
}

.primaryScenarioCard:hover,
.solverCompactCard:hover,
.featureControlCard:hover,
.compactWeatherProfileOption:hover,
.compactWeatherProfileOption:focus-visible {
  border-color: var(--line-strong) !important;
  background: var(--surface-hover) !important;
  box-shadow: none !important;
}

/* Reduce the game-like glow across ordinary cards and badges. */
.resultKpiCard,
.uxMetricCard,
.featureControlCard,
.validationPopupCard,
.primaryScenarioCard,
.solverCompactCard,
.workspaceBadge,
.status,
.resultsBadge,
.systemReadyBadge,
.readinessBadge {
  box-shadow: none !important;
}

/* ---------- Typography / contrast ---------- */
body,
button,
input,
select {
  color: var(--text);
}

p,
small,
.sectionTitle p,
.workspaceTop p,
.homeGrid .hero p,
.conclusion p,
.brand small,
.chartValue,
.resultKpiCard small,
.validationMetricPopoverExplanation,
.validationMetricPopoverSection.threshold p,
.actionLogReason,
.commitmentUnitLabel small,
.railControlHead > div:first-child > span,
.railInputMetaLine > span {
  color: var(--muted) !important;
}

.kicker,
.validationGateGroupLabel,
.resultKpiCard span,
.bitstringBox span,
.finalConclusionCard span,
.validationMetricPopoverSection > span {
  color: var(--muted-2) !important;
}

button:disabled,
input:disabled,
.disabled,
[aria-disabled="true"] {
  color: var(--disabled) !important;
}

.stressAxisText,
.stressYAxisText,
.stressAxisTitle,
.chartAxisText,
.chartAxisLabel,
.dispatchHour span,
.chartLabel,
th {
  color: var(--muted) !important;
  fill: var(--muted) !important;
}

/* ---------- Primary interaction: reserve cyan gradient ---------- */
.launchBtn,
.singleOptimizationCompound,
.singleOptimizationLaunch,
.navStep.active,
.weatherProfileTabs button.active,
.methodModalTabs button.active,
.primaryScenarioCard.active,
.compactWeatherProfileOption.active,
.exportScheduleButton,
.exportButton {
  border-color: rgba(0, 230, 195, 0.42) !important;
  color: #021713 !important;
  background: linear-gradient(135deg, var(--primary-action), var(--primary-highlight)) !important;
}

.primaryScenarioCard.active strong,
.primaryScenarioCard.active small,
.primaryScenarioCard.active .primaryScenarioIcon,
.weatherProfileTabs button.active,
.methodModalTabs button.active,
.singleOptimizationCompound .singleOptimizationLaunch,
.singleOptimizationCompound .singleOptimizationLaunch small,
.singleOptimizationCompound .singleOptimizationLaunch strong {
  color: #021713 !important;
}

.primaryScenarioCard.active,
.navStep.active,
.weatherProfileTabs button.active,
.methodModalTabs button.active,
.singleOptimizationCompound {
  box-shadow: 0 8px 22px rgba(0, 230, 195, 0.11) !important;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
.metric-value:focus-visible {
  outline: 2px solid var(--focus-ring) !important;
  outline-offset: 2px;
}

/* Ordinary badges are semantic, not action-gradient elements. */
.systemReadyBadge,
.workspaceBadge,
.status.online,
.resultsBadge,
.readinessBadge.safe {
  color: var(--success) !important;
  border-color: rgba(37, 217, 138, 0.3) !important;
  background: rgba(37, 217, 138, 0.075) !important;
}

/* ---------- Semantic statuses ---------- */
.validationPopupCard.safe .decisionStatusDot,
.readinessBadge.safe i,
.status.online span,
.launchStatusFooter > i {
  background: var(--success) !important;
  box-shadow: 0 0 0 2px rgba(37, 217, 138, 0.09) !important;
}

.validationPopupCard.safe .validationMetricValue,
.validationPopupCard.safe .validationPopupCopy strong,
.readinessBadge.safe,
.portalValidationMetricPopover.safe .validationMetricPopoverHeader strong {
  color: var(--success) !important;
  border-bottom-color: rgba(37, 217, 138, 0.5) !important;
}

.validationPopupCard.info .decisionStatusDot {
  background: var(--info) !important;
  box-shadow: none !important;
}

.validationPopupCard.info .validationMetricValue,
.validationPopupCard.info .validationPopupCopy strong,
.metric-value--info,
.portalValidationMetricPopover.info .validationMetricPopoverHeader strong {
  color: var(--info) !important;
  border-bottom-color: rgba(34, 211, 238, 0.55) !important;
}

.validationPopupCard.watch .decisionStatusDot,
.readinessBadge.watch i {
  background: var(--warning) !important;
  box-shadow: none !important;
}

.validationPopupCard.watch .validationMetricValue,
.validationPopupCard.watch .validationPopupCopy strong,
.metric-value--watch,
.portalValidationMetricPopover.watch .validationMetricPopoverHeader strong {
  color: var(--warning) !important;
  border-bottom-color: rgba(246, 200, 95, 0.58) !important;
}

.validationPopupCard.risk .decisionStatusDot,
.readinessBadge.risk i {
  background: var(--risk) !important;
  box-shadow: none !important;
}

.validationPopupCard.risk .validationMetricValue,
.validationPopupCard.risk .validationPopupCopy strong,
.metric-value--risk,
.readinessBadge.risk,
.portalValidationMetricPopover.risk .validationMetricPopoverHeader strong {
  color: var(--risk) !important;
  border-bottom-color: rgba(255, 77, 120, 0.62) !important;
}

/* Available / Renewable share are informational rather than "passed". */
.validationPopupCard.info {
  border-color: transparent !important;
}

/* ---------- Action Log status language ---------- */
.actionLogStatus.on {
  color: var(--success) !important;
}

.actionLogStatus.running {
  color: var(--info) !important;
}

.actionLogStatus.off,
.actionLogStatus.neutral {
  color: #77958d !important;
}

.actionLogStatus.discharge {
  color: var(--warning) !important;
}

.actionLogStatus.charge {
  color: var(--data-battery) !important;
}

.actionLogStatus.grid {
  color: var(--data-grid) !important;
}

.actionLogStatus.danger {
  color: var(--risk) !important;
}

/* Generator schedule: Running is informational; transitions stay semantic. */
.commitmentCell.off,
.commitmentLegend i.off {
  border-color: rgba(49, 79, 72, 0.72) !important;
  background: var(--neutral) !important;
}

.commitmentCell.on {
  border-color: rgba(34, 211, 238, 0.42) !important;
  background: linear-gradient(180deg, rgba(34, 211, 238, 0.88), rgba(22, 201, 232, 0.62)) !important;
  box-shadow: none !important;
}

.commitmentLegend i.on {
  background: var(--info) !important;
}

.commitmentEvent.startup,
.commitmentLegend i.event {
  background: var(--success) !important;
}

.commitmentEvent.shutdown {
  background: var(--risk) !important;
}

.commitmentCell.stress::after,
.stressWindowShade {
  background: var(--data-stress-window) !important;
  fill: var(--data-stress-window) !important;
}

/* ---------- Physical-data palette: Workspace ---------- */
.stressPath.load,
.stressLegend i.load {
  stroke: var(--data-load) !important;
  background: var(--data-load) !important;
}

.stressPath.vre,
.stressLegend i.vre {
  stroke: var(--data-renewable) !important;
  background: var(--data-renewable) !important;
}

.stressPath.residual,
.stressLegend i.residual {
  stroke: var(--data-residual) !important;
  background: var(--data-residual) !important;
}

.gridSupportLimit,
.stressLegend i.grid-limit {
  stroke: var(--data-grid-limit) !important;
  background: var(--data-grid-limit) !important;
}

.gridSupportLimitLabel {
  fill: var(--data-grid-limit) !important;
  color: var(--data-grid-limit) !important;
  filter: none !important;
}

.criticalGapBars rect,
.stressLegend i.critical {
  fill: rgba(255, 63, 108, 0.16) !important;
  stroke: rgba(255, 63, 108, 0.55) !important;
  background: rgba(255, 63, 108, 0.28) !important;
}

.stressGridLines line,
.stressVerticalGrid line,
.chartGridLine,
.gridLine {
  stroke: rgba(145, 175, 167, 0.12) !important;
}

/* Operating-input sliders retain physical meaning. */
.featureRange.load,
.featureControlCard.load {
  --feature-color: var(--data-load) !important;
}

.featureRange.solar,
.featureControlCard.solar {
  --feature-color: var(--data-solar) !important;
}

.featureRange.wind,
.featureControlCard.wind {
  --feature-color: var(--data-wind) !important;
}

.featureRange.grid,
.featureControlCard.grid {
  --feature-color: var(--data-grid) !important;
}

.featureRange.battery,
.featureControlCard.battery {
  --feature-color: var(--data-battery) !important;
}

/* ---------- Physical-data palette: Results charts ---------- */
.dispatchSegment.solar,
.legend i.solar {
  background: var(--data-solar) !important;
}

.dispatchSegment.wind,
.legend i.wind {
  background: var(--data-wind) !important;
}

.dispatchSegment.battery,
.legend i.battery,
.breakdownFill.battery,
.costDonutSegment.battery,
.costDonutTooltip.battery::before {
  background-color: var(--data-battery) !important;
  stroke: var(--data-battery) !important;
  color: var(--data-battery) !important;
}

.dispatchSegment.grid,
.legend i.grid,
.breakdownFill.grid,
.costDonutSegment.grid,
.costDonutTooltip.grid::before {
  background-color: var(--data-grid) !important;
  stroke: var(--data-grid) !important;
  color: var(--data-grid) !important;
}

.dispatchSegment.diesel,
.legend i.diesel,
.breakdownFill.diesel,
.costDonutSegment.diesel,
.costDonutTooltip.diesel::before {
  background-color: var(--data-diesel) !important;
  stroke: var(--data-diesel) !important;
  color: var(--data-diesel) !important;
}

.legend i.loadLine {
  background: var(--data-load) !important;
}

.breakdownFill.startup,
.costDonutSegment.startup,
.costDonutTooltip.startup::before {
  background-color: var(--warning) !important;
  stroke: var(--warning) !important;
  color: var(--warning) !important;
}

