:root {
  --operation-running: #12df91;
  --operation-off: #24443e;
  --operation-off-text: #47645d;
  --operation-start: #22d3ee;
  --operation-stop: #ff4d78;
  --operation-battery: #c35cf5;
  --operation-warning: #f6c85f;
  --operation-time: #91afa7;
  --operation-asset: #ecf8f4;
  --operation-note: #6f9188;
}

/* ---------- Unit Schedule ---------- */
.commitmentCell.on {
  border-color: rgba(18, 223, 145, 0.42) !important;
  background: linear-gradient(
    180deg,
    rgba(18, 223, 145, 0.94),
    rgba(18, 223, 145, 0.66)
  ) !important;
  box-shadow: none !important;
}

.commitmentCell.off {
  border-color: rgba(71, 100, 93, 0.38) !important;
  background: var(--operation-off) !important;
  box-shadow: none !important;
}

.commitmentEvent.startup {
  border-radius: 50% !important;
  background: var(--operation-start) !important;
}

.commitmentEvent.shutdown {
  border-radius: 2px !important;
  background: var(--operation-stop) !important;
}

.commitmentCell.stress::after {
  background: rgba(246, 200, 95, 0.10) !important;
}

.commitmentLegend i.on {
  border: 1px solid rgba(18, 223, 145, 0.35) !important;
  border-radius: 3px !important;
  background: var(--operation-running) !important;
}

.commitmentLegend i.off {
  border: 1px solid rgba(71, 100, 93, 0.46) !important;
  border-radius: 3px !important;
  background: var(--operation-off) !important;
}

.commitmentLegend i.start {
  width: 7px !important;
  height: 7px !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: var(--operation-start) !important;
}

.commitmentLegend i.stop {
  width: 8px !important;
  height: 8px !important;
  border: 0 !important;
  border-radius: 2px !important;
  background: var(--operation-stop) !important;
}

.commitmentLegend i.stress {
  border: 1px solid rgba(246, 200, 95, 0.38) !important;
  border-radius: 3px !important;
  background: rgba(246, 200, 95, 0.22) !important;
}

/* ---------- Action Log neutral columns ---------- */
.actionLogTableHead {
  color: var(--muted) !important;
}

.actionLogRow .operatingEventTime,
.operatingEventTime {
  color: var(--operation-time) !important;
  text-shadow: none !important;
  font-weight: 750 !important;
}

.actionLogAsset b {
  color: var(--operation-asset) !important;
}

.actionLogReason,
.actionLogNoteButton {
  color: var(--operation-note) !important;
}

/* ---------- Action column: marker + event color ---------- */
.actionLogAction {
  display: inline-flex !important;
  align-items: center;
  gap: 7px;
  color: var(--operation-time) !important;
  font-weight: 800 !important;
}

.actionLogAction > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.actionLogActionMarker {
  flex: 0 0 auto;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: none;
}

.actionLogAction.running {
  color: var(--operation-running) !important;
}

.actionLogAction.start,
.actionLogAction.grid {
  color: var(--operation-start) !important;
}

.actionLogAction.stop {
  color: var(--operation-stop) !important;
}

.actionLogAction.stop .actionLogActionMarker {
  border-radius: 2px;
}

.actionLogAction.battery {
  color: var(--operation-battery) !important;
}

.actionLogAction.battery .actionLogActionMarker {
  border-radius: 2px;
  transform: rotate(45deg);
}

.actionLogAction.warning {
  color: var(--operation-warning) !important;
}

.actionLogAction.danger {
  color: var(--operation-stop) !important;
}

.actionLogAction.neutral {
  color: var(--operation-time) !important;
}

/* ---------- Status column: resulting state / output ---------- */
.actionLogStatus.on,
.actionLogStatus.running,
.actionLogStatus.grid {
  color: var(--operation-running) !important;
}

.actionLogStatus.off,
.actionLogStatus.neutral {
  color: var(--operation-off-text) !important;
}

.actionLogStatus.battery,
.actionLogStatus.charge,
.actionLogStatus.discharge {
  color: var(--operation-battery) !important;
}

.actionLogStatus.warning {
  color: var(--operation-warning) !important;
}

.actionLogStatus.danger {
  color: var(--operation-stop) !important;
}

/* ---------- Hover / linked-hour row treatment ---------- */
.actionLogRow {
  --action-color: var(--operation-time);
  position: relative;
  border-left: 2px solid transparent !important;
  transition:
    background-color 140ms ease,
    box-shadow 140ms ease,
    border-color 140ms ease;
}

.actionLogRow.actionTone-running {
  --action-color: var(--operation-running);
}

.actionLogRow.actionTone-start,
.actionLogRow.actionTone-grid {
  --action-color: var(--operation-start);
}

.actionLogRow.actionTone-stop,
.actionLogRow.actionTone-danger {
  --action-color: var(--operation-stop);
}

.actionLogRow.actionTone-battery {
  --action-color: var(--operation-battery);
}

.actionLogRow.actionTone-warning {
  --action-color: var(--operation-warning);
}

.actionLogRow:hover,
.actionLogRow:focus-visible,
.actionLogRow.active {
  border-left-color: var(--action-color) !important;
  background: rgba(18, 223, 145, 0.06) !important;
  outline: none !important;
  box-shadow: none !important;
}

.actionLogRow:focus-visible {
  box-shadow: inset 0 0 0 1px rgba(145, 175, 167, 0.18) !important;
}

@media (max-width: 720px) {
  .actionLogAction {
    gap: 6px;
  }

  .actionLogActionMarker {
    width: 5px;
    height: 5px;
  }
}


