/* ============================================================
   v93 — final Page 02 typography system + refined action card
   ============================================================ */

:root {
  --page2-text-primary: #ecf8f4;
  --page2-text-secondary: #91afa7;
  --page2-text-muted: #6f9188;
  --page2-action-mint: #22d7bf;
  --page2-action-aqua: #31c9d5;
  --page2-action-ink: #03201b;
}

/* ---------- One type family / one rhythm ---------- */
.workspaceLaunchpad,
.workspaceLaunchpad button,
.workspaceLaunchpad input,
.workspaceLaunchpad select,
.portalValidationMetricPopover,
.compactWeatherProfilePopover,
.weatherProfileDrawerPanel {
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;
}

/* ---------- Level 1: page title ---------- */
.workspaceLaunchpad .workspaceTop.launchpadIntro {
  min-height: 82px !important;
  padding: 4px 2px 8px !important;
}

.workspaceLaunchpad .launchpadIntro .pageHeaderCopy .kicker {
  margin-bottom: 7px !important;
  color: rgba(34, 215, 191, 0.88) !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  letter-spacing: 0.12em !important;
