}

.workspaceLaunchpad .launchpadIntro h2 {
  margin: 0 !important;
  color: var(--page2-text-primary) !important;
  font-size: clamp(38px, 2.85vw, 48px) !important;
  font-weight: 700 !important;
  line-height: 1.06 !important;
  letter-spacing: -0.02em !important;
}

/* ---------- Level 2: section / card titles ---------- */
.scenarioLaunchpadHead h3,
.chartStageHead h3 {
  color: var(--page2-text-primary) !important;
  font-size: clamp(22px, 1.6vw, 27px) !important;
  font-weight: 700 !important;
  line-height: 1.18 !important;
  letter-spacing: -0.01em !important;
}

.railControlHead h3,
.systemCheckSummaryHead h3 {
  color: var(--page2-text-primary) !important;
  font-size: 22px !important;
  font-weight: 700 !important;
  line-height: 1.2 !important;
  letter-spacing: -0.01em !important;
}

/* Descriptions under same-level card titles */
.scenarioLaunchpadHead > div:first-child > span,
.chartStageHead p,
.railControlHead > div:first-child > span,
.systemCheckSummaryHead > div > span {
  color: var(--page2-text-secondary) !important;
