}

.railOperatingInputs,
.unifiedValidationGate,
.scenarioHorizontalSection,
.operationalStressPanel {
  box-shadow: none !important;
}

/* ---------- Refined primary CTA ---------- */
.controlValidationTower .singleOptimizationCompound,
.singleOptimizationCompound {
  width: 100% !important;
  height: 92px !important;
  min-height: 92px !important;
  overflow: hidden !important;
  border: 1px solid rgba(103, 234, 218, 0.72) !important;
  border-radius: 20px !important;
  color: var(--page2-action-ink) !important;
  background:
    linear-gradient(
      120deg,
      var(--page2-action-mint) 0%,
      #27d3c5 48%,
      var(--page2-action-aqua) 100%
    ) !important;
  box-shadow:
    0 10px 24px rgba(14, 174, 157, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.22) !important;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    filter 160ms ease !important;
}

.singleOptimizationCompound.ready:hover,
.singleOptimizationCompound.ready:focus-within {
  border-color: rgba(208, 255, 248, 0.86) !important;
  filter: brightness(1.035) saturate(0.96) !important;
  transform: translateY(-1px) !important;
  box-shadow:
    0 14px 30px rgba(14, 174, 157, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
}

.controlValidationTower .singleOptimizationCompound .singleOptimizationLaunch,
.singleOptimizationCompound .singleOptimizationLaunch {
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 18px !important;
  padding: 16px 20px 16px 22px !important;
  border: 0 !important;
  border-radius: inherit !important;
  color: var(--page2-action-ink) !important;
  background: transparent !important;
  box-shadow: none !important;
  text-align: left !important;
}

.singleOptimizationCompound .singleOptimizationCopy {
  min-width: 0;
  display: flex !important;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: flex-start !important;
  justify-content: center;
  gap: 6px !important;
  text-align: left !important;
}

.controlValidationTower .singleOptimizationCompound .singleOptimizationLaunch strong,
.singleOptimizationCompound .singleOptimizationLaunch strong {
  width: auto !important;
  margin: 0 !important;
  color: var(--page2-action-ink) !important;
  font-size: 20px !important;
  font-weight: 700 !important;
  line-height: 1.08 !important;
  letter-spacing: -0.01em !important;
  text-align: left !important;
}

.controlValidationTower .singleOptimizationCompound .singleOptimizationLaunch small,
.singleOptimizationCompound .singleOptimizationLaunch small {
  display: block !important;
  max-width: 100%;
  overflow: hidden;
  color: rgba(3, 32, 27, 0.7) !important;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px !important;
  font-weight: 600 !important;
  line-height: 1.2 !important;
  letter-spacing: 0 !important;
}

.singleOptimizationCompound .singleOptimizationArrow {
  flex: 0 0 auto;
  display: grid !important;
  place-items: center;
  width: 40px !important;
  height: 40px !important;
  margin: 0 !important;
  border: 1px solid rgba(3, 32, 27, 0.2) !important;
  border-radius: 999px !important;
